 10→use crate::{Error, Result, types::AuthMode};
 11→
 12→type HmacSha256 = Hmac<Sha256>;
 13→
 14→/// Verify an inbound webhook request against the configured auth mode.
 15→pub fn verify(
 16→    mode: &AuthMode,
 17→    config: Option<&serde_json::Value>,
 18→    headers: &HeaderMap,
 19→    body: &[u8],
 20→) -> Result<()> {
 21→    match mode {
 22→        AuthMode::None => Ok(()),
 23→        AuthMode::StaticHeader => verify_static_header(config, headers),
 24→        AuthMode::Bearer => verify_bearer(config, headers),
 25→        AuthMode::GithubHmacSha256 => verify_github_hmac(config, headers, body),
 26→        AuthMode::GitlabToken => verify_gitlab_token(config, headers),
 27→        AuthMode::StripeWebhookSignature => verify_stripe_signature(config, headers, body),
 28→        AuthMode::LinearWebhookSignature => verify_linear_signature(config, headers, body),
 29→        AuthMode::PagerdutyV2Signature => verify_pagerduty_signature(config, headers, body),
 30→        AuthMode::SentryWebhookSignature => verify_sentry_signature(config, headers, body),
 31→    }
 32→}
 33→
 34→fn get_config_str<'a>(config: Option<&'a serde_json::Value>, key: &str) -> Result<&'a str> {
 35→    config
 36→        .and_then(|c| c.get(key))
 37→        .and_then(|v| v.as_str())
 38→        .ok_or_else(|| Error::auth_failed(format!("missing auth config key: {key}")))
 39→}
 40→
 41→fn get_header_str<'a>(headers: &'a HeaderMap, name: &str) -> Result<&'a str> {
 42→    headers
 43→        .get(name)
 44→        .and_then(|v| v.to_str().ok())
 45→        .ok_or_else(|| Error::auth_failed(format!("missing header: {name}")))
 46→}
 47→
 48→fn verify_static_header(config: Option<&serde_json::Value>, headers: &HeaderMap) -> Result<()> {
 49→    let header_name = get_config_str(config, "header")?;
 50→    let expected = get_config_str(config, "value")?;
 51→    let actual = get_header_str(headers, header_name)?;
 52→    if actual.as_bytes().ct_eq(expected.as_bytes()).into() {
 53→        Ok(())
 54→    } else {
 55→        Err(Error::auth_failed("static header mismatch"))
 56→    }
 57→}
 58→
 59→fn verify_bearer(config: Option<&serde_json::Value>, headers: &HeaderMap) -> Result<()> {
 60→    let expected = get_config_str(config, "token")?;
 61→    let auth = get_header_str(headers, "authorization")?;
 62→    let token = auth
 63→        .strip_prefix("Bearer ")
 64→        .ok_or_else(|| Error::auth_failed("invalid Bearer format"))?;
 65→    if token.as_bytes().ct_eq(expected.as_bytes()).into() {
 66→        Ok(())
 67→    } else {
 68→        Err(Error::auth_failed("bearer token mismatch"))
 69→    }
 70→}
 71→
 72→fn verify_github_hmac(
 73→    config: Option<&serde_json::Value>,
 74→    headers: &HeaderMap,
 75→    body: &[u8],
 76→) -> Result<()> {
 77→    let secret = get_config_str(config, "secret")?;
 78→    let sig_header = get_header_str(headers, "x-hub-signature-256")?;
 79→    let sig_hex = sig_header
 80→        .strip_prefix("sha256=")
 81→        .ok_or_else(|| Error::auth_failed("invalid signature format"))?;
 82→    let sig_bytes =
 83→        hex::decode(sig_hex).map_err(|_| Error::auth_failed("invalid signature hex"))?;
 84→
 85→    let mut mac = HmacSha256::new_from_slice(secret.as_bytes())
 86→        .map_err(|e| Error::auth_failed(e.to_string()))?;
 87→    mac.update(body);
 88→    let expected = mac.finalize().into_bytes();
 89→
 90→    if expected[..].ct_eq(&sig_bytes).into() {
 91→        Ok(())
 92→    } else {
 93→        Err(Error::auth_failed("HMAC signature mismatch"))
 94→    }
 95→}
 96→
 97→fn verify_gitlab_token(config: Option<&serde_json::Value>, headers: &HeaderMap) -> Result<()> {
 98→    let expected = get_config_str(config, "token")?;
 99→    let actual = get_header_str(headers, "x-gitlab-token")?;
100→    if actual.as_bytes().ct_eq(expected.as_bytes()).into() {
101→        Ok(())
102→    } else {
103→        Err(Error::auth_failed("GitLab token mismatch"))
104→    }
105→}
106→
107→fn verify_stripe_signature(
108→    config: Option<&serde_json::Value>,
109→    headers: &HeaderMap,
110→    body: &[u8],
111→) -> Result<()> {
112→    let secret = get_config_str(config, "secret")?;
113→    let sig_header = get_header_str(headers, "stripe-signature")?;
114→
115→    // Parse "t=TIMESTAMP,v1=SIG" format
116→    let mut timestamp = None;
117→    let mut signatures = Vec::new();
118→    for part in sig_header.split(',') {
119→        let mut kv = part.splitn(2, '=');
120→        match (kv.next(), kv.next()) {
121→            (Some("t"), Some(ts)) => timestamp = Some(ts),
122→            (Some("v1"), Some(sig)) => signatures.push(sig.to_string()),
123→            _ => {},
124→        }
125→    }
126→    let ts =
127→        timestamp.ok_or_else(|| Error::auth_failed("missing timestamp in Stripe signature"))?;
128→    if signatures.is_empty() {
129→        return Err(Error::auth_failed("missing v1 signature"));
130→    }
131→
132→    // Check timestamp tolerance (5 minutes). Fail closed on non-numeric timestamps.
133→    let ts_secs = ts
134→        .parse::<i64>()
135→        .map_err(|_| Error::auth_failed("invalid Stripe signature timestamp"))?;
136→    let now = time::OffsetDateTime::now_utc().unix_timestamp();
137→    if (now - ts_secs).unsigned_abs() > 300 {
138→        return Err(Error::auth_failed("Stripe signature timestamp too old"));
139→    }
140→
141→    // Compute expected signature: HMAC-SHA256(secret, "timestamp.body")
142→    // Concatenate as raw bytes to avoid lossy UTF-8 conversion.
143→    let mut mac = HmacSha256::new_from_slice(secret.as_bytes())
144→        .map_err(|e| Error::auth_failed(e.to_string()))?;
145→    mac.update(format!("{ts}.").as_bytes());
146→    mac.update(body);
147→    let expected = hex::encode(mac.finalize().into_bytes());
148→
149→    if signatures
150→        .iter()
151→        .any(|s| s.as_bytes().ct_eq(expected.as_bytes()).into())
152→    {
153→        Ok(())
154→    } else {
155→        Err(Error::auth_failed("Stripe signature mismatch"))
156→    }
157→}
158→
159→fn verify_linear_signature(
160→    config: Option<&serde_json::Value>,
161→    headers: &HeaderMap,
162→    body: &[u8],
163→) -> Result<()> {
164→    verify_hmac_header(
165→        config,
166→        headers,
167→        body,
168→        "linear-signature",
169→        "secret",
170→        "sha256=",
171→    )
172→}
173→
174→fn verify_pagerduty_signature(
175→    config: Option<&serde_json::Value>,
176→    headers: &HeaderMap,
177→    body: &[u8],
178→) -> Result<()> {
179→    // PagerDuty sends comma-separated "v1=SIG1,v1=SIG2" during key rotation.
180→    let secret = get_config_str(config, "secret")?;
181→    let sig_header = get_header_str(headers, "x-pagerduty-signature")?;
182→
183→    let mut mac = HmacSha256::new_from_slice(secret.as_bytes())
184→        .map_err(|e| Error::auth_failed(e.to_string()))?;
185→    mac.update(body);
186→    let expected = hex::encode(mac.finalize().into_bytes());
187→
188→    // Check each comma-separated signature entry.
189→    let matched = sig_header.split(',').any(|part| {
190→        let part = part.trim();
191→        if let Some(sig_hex) = part.strip_prefix("v1=") {
192→            sig_hex.as_bytes().ct_eq(expected.as_bytes()).into()
193→        } else {
194→            false
195→        }
196→    });
197→
198→    if matched {
199→        Ok(())
200→    } else {
201→        Err(Error::auth_failed("x-pagerduty-signature mismatch"))
202→    }
203→}
204→
205→fn verify_sentry_signature(
206→    config: Option<&serde_json::Value>,
207→    headers: &HeaderMap,
208→    body: &[u8],
209→) -> Result<()> {
210→    verify_hmac_header(config, headers, body, "sentry-hook-signature", "secret", "")
211→}
