213→/// Generic HMAC-SHA256 header verifier.
214→fn verify_hmac_header(
215→    config: Option<&serde_json::Value>,
216→    headers: &HeaderMap,
217→    body: &[u8],
218→    header_name: &str,
219→    config_key: &str,
220→    prefix: &str,
221→) -> Result<()> {
222→    let secret = get_config_str(config, config_key)?;
223→    let sig_header = get_header_str(headers, header_name)?;
224→    let sig_hex = if prefix.is_empty() {
225→        sig_header
226→    } else {
227→        sig_header
228→            .strip_prefix(prefix)
229→            .ok_or_else(|| Error::auth_failed(format!("invalid {header_name} format")))?
230→    };
231→    let sig_bytes =
232→        hex::decode(sig_hex).map_err(|_| Error::auth_failed("invalid signature hex"))?;
233→
234→    let mut mac = HmacSha256::new_from_slice(secret.as_bytes())
235→        .map_err(|e| Error::auth_failed(e.to_string()))?;
236→    mac.update(body);
237→    let expected = mac.finalize().into_bytes();
238→
239→    if expected[..].ct_eq(&sig_bytes).into() {
240→        Ok(())
241→    } else {
242→        Err(Error::auth_failed(format!("{header_name} mismatch")))
243→    }
244→}
