109→fn row_to_webhook(row: &sqlx::sqlite::SqliteRow) -> Result<Webhook> {
110→    let auth_mode_str: String = row.get("auth_mode");
111→    let auth_mode: AuthMode =
112→        serde_json::from_value(serde_json::Value::String(auth_mode_str)).unwrap_or_default();
113→    let session_mode_str: String = row.get("session_mode");
114→    let session_mode: SessionMode =
115→        serde_json::from_value(serde_json::Value::String(session_mode_str)).unwrap_or_default();
116→    let tool_policy: Option<ToolPolicy> = row
117→        .get::<Option<String>, _>("tool_policy_json")
118→        .and_then(|s| serde_json::from_str(&s).ok());
119→    let event_filter: EventFilter = row
120→        .get::<Option<String>, _>("event_filter_json")
121→        .and_then(|s| serde_json::from_str(&s).ok())
122→        .unwrap_or_default();
123→    let allowed_cidrs: Vec<String> = row
124→        .get::<Option<String>, _>("allowed_cidrs_json")
125→        .and_then(|s| serde_json::from_str(&s).ok())
126→        .unwrap_or_default();
127→    let auth_config: Option<serde_json::Value> = row
128→        .get::<Option<String>, _>("auth_config_json")
129→        .and_then(|s| serde_json::from_str(&s).ok());
130→    let source_config: Option<serde_json::Value> = row
131→        .get::<Option<String>, _>("source_config_json")
132→        .and_then(|s| serde_json::from_str(&s).ok());
133→
134→    Ok(Webhook {
135→        id: row.get("id"),
136→        name: row.get("name"),
137→        description: row.get("description"),
138→        enabled: row.get::<i32, _>("enabled") != 0,
139→        public_id: row.get("public_id"),
140→        agent_id: row.get("agent_id"),
141→        model: row.get("model"),
142→        system_prompt_suffix: row.get("system_prompt_suffix"),
143→        tool_policy,
144→        auth_mode,
145→        auth_config,
146→        source_profile: row.get("source_profile"),
147→        source_config,
148→        event_filter,
149→        session_mode,
150→        named_session_key: row.get("named_session_key"),
151→        allowed_cidrs,
152→        max_body_bytes: row.get::<i64, _>("max_body_bytes") as usize,
153→        rate_limit_per_minute: row.get::<i64, _>("rate_limit_per_minute") as u32,
154→        delivery_count: row.get::<i64, _>("delivery_count") as u64,
155→        last_delivery_at: row.get("last_delivery_at"),
156→        created_at: row.get("created_at"),
157→        updated_at: row.get("updated_at"),
158→    })
159→}
160→
161→fn row_to_delivery(row: &sqlx::sqlite::SqliteRow) -> Result<WebhookDelivery> {
162→    let status_str: String = row.get("status");
163→    let status: DeliveryStatus = serde_json::from_value(serde_json::Value::String(status_str))
164→        .unwrap_or(DeliveryStatus::Received);
165→
166→    Ok(WebhookDelivery {
167→        id: row.get("id"),
168→        webhook_id: row.get("webhook_id"),
169→        received_at: row.get("received_at"),
170→        status,
171→        event_type: row.get("event_type"),
172→        entity_key: row.get("entity_key"),
173→        delivery_key: row.get("delivery_key"),
174→        http_method: row.get("http_method"),
175→        content_type: row.get("content_type"),
176→        remote_ip: row.get("remote_ip"),
177→        headers_json: row.get("headers_json"),
178→        body_size: row.get::<i64, _>("body_size") as usize,
179→        session_key: row.get("session_key"),
180→        rejection_reason: row.get("rejection_reason"),
181→        run_error: row.get("run_error"),
182→        started_at: row.get("started_at"),
183→        finished_at: row.get("finished_at"),
184→        duration_ms: row.try_get("duration_ms").ok().flatten(),
185→        input_tokens: row.try_get("input_tokens").ok().flatten(),
186→        output_tokens: row.try_get("output_tokens").ok().flatten(),
187→    })
188→}
