217→    async fn create_webhook(&self, create: WebhookCreate) -> Result<Webhook> {
218→        let public_id = generate_public_id();
219→        let now = now_iso();
220→        let auth_mode_str = serde_json::to_value(&create.auth_mode)?
221→            .as_str()
222→            .unwrap_or("static_header")
223→            .to_string();
224→        let session_mode_str = serde_json::to_value(&create.session_mode)?
225→            .as_str()
226→            .unwrap_or("per_delivery")
227→            .to_string();
228→        let tool_policy_json = create
229→            .tool_policy
230→            .as_ref()
231→            .map(serde_json::to_string)
232→            .transpose()?;
233→        let event_filter_json = serde_json::to_string(&create.event_filter)?;
234→        let auth_config_json = create
235→            .auth_config
236→            .as_ref()
237→            .map(serde_json::to_string)
238→            .transpose()?;
239→        let source_config_json = create
240→            .source_config
241→            .as_ref()
242→            .map(serde_json::to_string)
243→            .transpose()?;
244→        let allowed_cidrs_json = serde_json::to_string(&create.allowed_cidrs)?;
245→
246→        let result = sqlx::query(
247→            "INSERT INTO webhooks (name, description, public_id, agent_id, model, system_prompt_suffix, \
248→             tool_policy_json, auth_mode, auth_config_json, source_profile, source_config_json, \
249→             event_filter_json, session_mode, named_session_key, allowed_cidrs_json, \
250→             max_body_bytes, rate_limit_per_minute, created_at, updated_at) \
251→             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
252→        )
253→        .bind(&create.name)
254→        .bind(&create.description)
255→        .bind(&public_id)
256→        .bind(&create.agent_id)
257→        .bind(&create.model)
258→        .bind(&create.system_prompt_suffix)
259→        .bind(&tool_policy_json)
260→        .bind(&auth_mode_str)
261→        .bind(&auth_config_json)
262→        .bind(&create.source_profile)
263→        .bind(&source_config_json)
264→        .bind(&event_filter_json)
265→        .bind(&session_mode_str)
266→        .bind(&create.named_session_key)
267→        .bind(&allowed_cidrs_json)
268→        .bind(create.max_body_bytes as i64)
269→        .bind(create.rate_limit_per_minute as i64)
270→        .bind(&now)
271→        .bind(&now)
272→        .execute(&self.pool)
