389→    async fn delete_webhook(&self, id: i64) -> Result<()> {
390→        // Transaction prevents partial data loss if a later DELETE fails.
391→        let mut tx = self.pool.begin().await?;
392→        sqlx::query(
393→            "DELETE FROM webhook_response_actions WHERE delivery_id IN \
394→             (SELECT id FROM webhook_deliveries WHERE webhook_id = ?)",
395→        )
396→        .bind(id)
397→        .execute(&mut *tx)
398→        .await?;
399→        sqlx::query("DELETE FROM webhook_deliveries WHERE webhook_id = ?")
400→            .bind(id)
401→            .execute(&mut *tx)
402→            .await?;
403→        let result = sqlx::query("DELETE FROM webhooks WHERE id = ?")
404→            .bind(id)
405→            .execute(&mut *tx)
406→            .await?;
407→        if result.rows_affected() == 0 {
408→            return Err(Error::webhook_not_found(id.to_string()));
409→        }
410→        tx.commit().await?;
411→        Ok(())
412→    }
