 21→}
 22→
 23→/// Callback type for executing an agent turn.
 24→pub type ExecuteFn = Arc<
 25→    dyn Fn(ExecuteRequest) -> Pin<Box<dyn Future<Output = anyhow::Result<ProcessResult>> + Send>>
 26→        + Send
 27→        + Sync,
 28→>;
 29→
 30→/// Request to execute a webhook delivery.
 31→pub struct ExecuteRequest {
 32→    pub webhook_id: i64,
 33→    pub delivery_id: i64,
 34→    pub session_key: String,
