 40→
 41→/// Background worker that processes queued webhook deliveries.
 42→pub struct WebhookWorker {
 43→    rx: mpsc::Receiver<i64>,
 44→    store: Arc<dyn WebhookStore>,
 45→    execute_fn: ExecuteFn,
 46→}
 47→
 48→impl WebhookWorker {
 49→    pub fn new(
 50→        rx: mpsc::Receiver<i64>,
 51→        store: Arc<dyn WebhookStore>,
 52→        execute_fn: ExecuteFn,
 53→    ) -> Self {
 54→        Self {
 55→            rx,
 56→            store,
 57→            execute_fn,
 58→        }
 59→    }
 60→
 61→    /// Run the worker loop, processing deliveries from the channel.
 62→    ///
 63→    /// On startup, drains any deliveries left in `received` or `queued` state
 64→    /// from a previous run before listening for new work on the channel.
 65→    #[instrument(skip_all, name = "webhook_worker")]
 66→    pub async fn run(mut self) {
 67→        info!("webhook worker started");
 68→
 69→        // Crash recovery: re-process deliveries stuck from a previous run.
 70→        match self.store.list_unprocessed_deliveries().await {
 71→            Ok(ids) => {
 72→                if !ids.is_empty() {
 73→                    info!(
 74→                        count = ids.len(),
 75→                        "re-processing unfinished deliveries from previous run"
 76→                    );
 77→                }
 78→                for id in ids {
 79→                    if let Err(e) = self.process_delivery(id).await {
 80→                        error!(delivery_id = id, error = %e, "failed to reprocess existing delivery");
 81→                    }
 82→                }
 83→            },
 84→            Err(e) => error!(error = %e, "failed to load unprocessed deliveries at startup"),
 85→        }
 86→
 87→        while let Some(delivery_id) = self.rx.recv().await {
 88→            if let Err(e) = self.process_delivery(delivery_id).await {
 89→                error!(delivery_id, error = %e, "webhook delivery processing failed");
 90→            }
 91→        }
 92→        info!("webhook worker stopped");
 93→    }
 94→
 95→    #[instrument(skip(self), fields(delivery_id))]
 96→    async fn process_delivery(&self, delivery_id: i64) -> anyhow::Result<()> {
 97→        // Mark as processing
 98→        self.store
 99→            .update_delivery_status(delivery_id, DeliveryStatus::Processing, DeliveryUpdate {
100→                started_at: Some(now_iso()),
101→                ..Default::default()
102→            })
103→            .await
104→            .map_err(|e| anyhow::anyhow!("{e}"))?;
105→
106→        // Load delivery and webhook
107→        let delivery = self
108→            .store
109→            .get_delivery(delivery_id)
110→            .await
111→            .map_err(|e| anyhow::anyhow!("{e}"))?;
112→        let webhook = self
113→            .store
114→            .get_webhook(delivery.webhook_id)
115→            .await
116→            .map_err(|e| anyhow::anyhow!("{e}"))?;
117→
118→        // Load body for normalization
119→        let body_bytes = self
120→            .store
121→            .get_delivery_body(delivery_id)
122→            .await
123→            .map_err(|e| anyhow::anyhow!("{e}"))?
124→            .unwrap_or_default();
125→
126→        let body: serde_json::Value = serde_json::from_slice(&body_bytes).unwrap_or_default();
127→
128→        // Get the source profile for normalization
129→        let profile_registry = crate::profiles::ProfileRegistry::new();
130→        let profile = profile_registry.get(&webhook.source_profile);
131→
132→        // Normalize payload
133→        let event_type = delivery.event_type.as_deref().unwrap_or("unknown");
134→        let normalized = match profile {
135→            Some(p) => p.normalize_payload(event_type, &body),
136→            None => crate::profiles::generic::GenericProfile.normalize_payload(event_type, &body),
137→        };
138→
139→        // Build the delivery message
140→        let message = crate::normalize::build_delivery_message(
141→            &webhook,
142→            delivery.event_type.as_deref(),
143→            delivery.delivery_key.as_deref(),
144→            &delivery.received_at,
145→            &normalized.summary,
146→        );
147→
148→        let session_key = build_session_key(&webhook, delivery_id, delivery.entity_key.as_deref());
149→
150→        let start = std::time::Instant::now();
151→
152→        // Execute via callback
153→        let result = (self.execute_fn)(ExecuteRequest {
154→            webhook_id: webhook.id,
155→            delivery_id,
156→            session_key: session_key.clone(),
157→            agent_id: webhook.agent_id.clone(),
158→            model: webhook.model.clone(),
159→            tool_policy: webhook.tool_policy.clone(),
160→            message,
161→        })
162→        .await;
163→
164→        let duration_ms = start.elapsed().as_millis() as i64;
165→
166→        match result {
167→            Ok(process_result) => {
168→                self.store
169→                    .update_delivery_status(
170→                        delivery_id,
171→                        DeliveryStatus::Completed,
172→                        DeliveryUpdate {
173→                            session_key: Some(process_result.session_key),
174→                            finished_at: Some(now_iso()),
175→                            duration_ms: Some(duration_ms),
176→                            input_tokens: process_result.input_tokens,
177→                            output_tokens: process_result.output_tokens,
178→                            ..Default::default()
179→                        },
180→                    )
181→                    .await
182→                    .map_err(|e| anyhow::anyhow!("{e}"))?;
183→            },
184→            Err(e) => {
185→                warn!(delivery_id, error = %e, "webhook execution failed");
186→                self.store
187→                    .update_delivery_status(delivery_id, DeliveryStatus::Failed, DeliveryUpdate {
188→                        run_error: Some(e.to_string()),
189→                        finished_at: Some(now_iso()),
190→                        duration_ms: Some(duration_ms),
191→                        ..Default::default()
192→                    })
193→                    .await
194→                    .map_err(|e| anyhow::anyhow!("{e}"))?;
195→            },
196→        }
197→
198→        Ok(())
199→    }
200→}

