12→/// A source profile defines how to authenticate, parse, filter, normalize,
13→/// and respond to events from a specific webhook provider.
14→pub trait SourceProfile: Send + Sync {
15→    /// Profile identifier used in config and database.
16→    fn id(&self) -> &str;
17→
18→    /// Human-readable name for the UI.
19→    fn display_name(&self) -> &str;
20→
21→    /// Default auth mode for this profile.
22→    fn default_auth_mode(&self) -> AuthMode;
23→
24→    /// Known event types with descriptions for UI filter checkboxes.
25→    fn event_catalog(&self) -> Vec<EventCatalogEntry>;
26→
27→    /// Extract event type from request headers and/or body.
28→    fn parse_event_type(&self, headers: &HeaderMap, body: &[u8]) -> Option<String>;
29→
30→    /// Extract idempotency key from request.
31→    fn parse_delivery_key(&self, headers: &HeaderMap, body: &[u8]) -> Option<String>;
32→
33→    /// Extract entity key for per_entity session grouping.
34→    fn entity_key(&self, event_type: &str, body: &serde_json::Value) -> Option<String>;
35→
36→    /// Produce a structured summary of the payload for the agent prompt.
37→    fn normalize_payload(&self, event_type: &str, body: &serde_json::Value) -> NormalizedPayload;
38→
39→    /// Whether this profile provides response tools.
40→    fn has_response_tools(&self) -> bool {
41→        false
42→    }
43→
44→    /// UI setup guidance markdown.
45→    fn setup_guide(&self) -> &str;
46→
47→    /// Build a summary for the profiles list RPC.
48→    fn summary(&self) -> ProfileSummary {
49→        ProfileSummary {
50→            id: self.id().into(),
51→            display_name: self.display_name().into(),
52→            default_auth_mode: self.default_auth_mode(),
53→            event_catalog: self.event_catalog(),
54→            has_response_tools: self.has_response_tools(),
55→            setup_guide: self.setup_guide().into(),
56→        }
57→    }
58→}
