 28→fn auth_secret_fields(mode: &AuthMode) -> &'static [&'static str] {
 29→    match mode {
 30→        AuthMode::None => &[],
 31→        AuthMode::StaticHeader => &["value"],
 32→        AuthMode::Bearer | AuthMode::GitlabToken => &["token"],
 33→        AuthMode::GithubHmacSha256
 34→        | AuthMode::StripeWebhookSignature
 35→        | AuthMode::LinearWebhookSignature
 36→        | AuthMode::PagerdutyV2Signature
 37→        | AuthMode::SentryWebhookSignature => &["secret"],
 38→    }
 39→}
