 41→fn source_secret_fields(_source_profile: &str) -> &'static [&'static str] {
 42→    &[
 43→        "access_token",
 44→        "api_key",
 45→        "api_token",
 46→        "bearer_token",
 47→        "client_secret",
 48→        "secret",
 49→        "signing_secret",
 50→        "token",
 51→        "webhook_secret",
 52→    ]
 53→}
 54→
 55→#[cfg(feature = "vault")]
 56→fn secret_store_error(
 57→    context: &'static str,
 58→    source: moltis_secret_store::Error,
 59→) -> moltis_webhooks::Error {
 60→    moltis_webhooks::Error::external(context, source)
 61→}
 62→
 63→#[cfg(feature = "vault")]
 64→async fn encrypt_secret_config(
 65→    config: &mut Option<Value>,
 66→    secret_fields: &[&str],
 67→    vault: Option<&Arc<moltis_vault::Vault>>,
 68→) -> moltis_webhooks::Result<()> {
 69→    if secret_fields.is_empty() {
 70→        return Ok(());
 71→    }
 72→
 73→    let Some(config) = config.as_mut() else {
 74→        return Ok(());
 75→    };
 76→
 77→    let Some(vault) = vault else {
 78→        return Ok(());
 79→    };
 80→
 81→    if vault.is_unsealed().await {
 82→        encrypt_secret_fields(
 83→            config,
 84→            secret_fields,
 85→            WEBHOOK_SECRET_AAD_SCOPE,
 86→            vault.as_ref(),
 87→        )
 88→        .await
 89→        .map_err(|error| secret_store_error("encrypt webhook secrets", error))?;
 90→        return Ok(());
 91→    }
 92→
 93→    let status = vault
 94→        .status()
 95→        .await
 96→        .map_err(|error| moltis_webhooks::Error::external("check vault status", error))?;
 97→    if matches!(status, VaultStatus::Uninitialized) {
 98→        return Ok(());
 99→    }
100→
101→    let has_plaintext = has_plaintext_secret_fields(config, secret_fields)
102→        .map_err(|error| secret_store_error("inspect plaintext webhook secrets", error))?;
103→    if has_plaintext {
104→        return Err(moltis_webhooks::Error::message(
105→            "vault is sealed; webhook secrets cannot be persisted",
106→        ));
107→    }
108→
109→    Ok(())
110→}
