113→pub async fn decrypt_webhook_secrets(
114→    webhook: &mut Webhook,
115→    vault: Option<&Arc<moltis_vault::Vault>>,
116→) -> anyhow::Result<()> {
117→    decrypt_secret_config(
118→        &mut webhook.auth_config,
119→        auth_secret_fields(&webhook.auth_mode),
120→        vault,
121→    )
122→    .await?;
123→    decrypt_secret_config(
124→        &mut webhook.source_config,
125→        source_secret_fields(&webhook.source_profile),
126→        vault,
127→    )
128→    .await?;
129→    Ok(())
130→}
