  5→/// Truncate a string to at most `max_bytes` without splitting a UTF-8 codepoint.
  6→pub fn truncate_str(s: &str, max_bytes: usize) -> &str {
  7→    if s.len() <= max_bytes {
  8→        return s;
  9→    }
 10→    // Walk backwards from max_bytes to find a char boundary.
 11→    let mut end = max_bytes;
 12→    while end > 0 && !s.is_char_boundary(end) {
 13→        end -= 1;
 14→    }
 15→    &s[..end]
 16→}
