 53→/// Extract selected headers from a request for logging.
 54→/// Only includes headers that are useful for debugging; skips auth secrets.
 55→pub fn extract_safe_headers(headers: &axum::http::HeaderMap) -> serde_json::Value {
 56→    let safe_prefixes = [
 57→        "x-github-",
 58→        "x-gitlab-",
 59→        "x-stripe-",
 60→        "x-pagerduty-",
 61→        "x-linear-",
 62→        "x-sentry-",
 63→        "x-request-id",
 64→        "x-delivery-id",
 65→        "x-event-type",
 66→        "content-type",
 67→        "content-length",
 68→        "user-agent",
 69→        "idempotency-key",
 70→    ];
 71→    let deny = [
 72→        "authorization",
 73→        "x-gitlab-token",
 74→        "cookie",
 75→        // HMAC signatures — not secrets themselves but provide a signature
 76→        // oracle if logged alongside the stored body.
 77→        "x-hub-signature-256",
 78→        "x-pagerduty-signature",
 79→        "stripe-signature",
 80→        "linear-signature",
 81→        "sentry-hook-signature",
 82→    ];
 83→
 84→    let mut map = serde_json::Map::new();
 85→    for (name, value) in headers {
 86→        let name_lower = name.as_str().to_lowercase();
 87→        if deny.iter().any(|d| name_lower == *d) {
 88→            continue;
 89→        }
 90→        if safe_prefixes
 91→            .iter()
 92→            .any(|prefix| name_lower.starts_with(prefix) || name_lower == *prefix)
 93→            && let Ok(v) = value.to_str()
 94→        {
 95→            map.insert(name_lower, serde_json::Value::String(v.into()));
 96→        }
 97→    }
 98→    serde_json::Value::Object(map)
 99→}
