  1→//! Per-webhook and global rate limiting.
  2→
  3→use std::{
  4→    collections::{HashMap, VecDeque},
  5→    sync::Mutex,
  6→};
  7→
  8→/// Combined state for per-webhook and global sliding windows.
  9→struct RateLimitState {
 10→    per_webhook: HashMap<i64, VecDeque<u64>>,
 11→    global: VecDeque<u64>,
 12→}
 13→
 14→/// Per-webhook sliding-window rate limiter.
 15→///
 16→/// Uses a single lock to avoid TOCTOU gaps between the global and
 17→/// per-webhook checks.
 18→pub struct WebhookRateLimiter {
 19→    state: Mutex<RateLimitState>,
 20→    global_max: u32,
 21→}
 22→
 23→impl WebhookRateLimiter {
 24→    /// Create a new rate limiter with a global max requests per minute.
 25→    pub fn new(global_max: u32) -> Self {
 26→        Self {
 27→            state: Mutex::new(RateLimitState {
 28→                per_webhook: HashMap::new(),
 29→                global: VecDeque::new(),
 30→            }),
 31→            global_max,
 32→        }
 33→    }
 34→
 35→    fn now_ms() -> u64 {
 36→        std::time::SystemTime::now()
 37→            .duration_since(std::time::UNIX_EPOCH)
 38→            .unwrap_or_default()
 39→            .as_millis() as u64
 40→    }
 41→
 42→    /// Check if a request is allowed for the given webhook.
 43→    /// Returns `true` if allowed, `false` if rate limited.
 44→    pub fn check(&self, webhook_id: i64, per_webhook_max: u32) -> bool {
 45→        let now = Self::now_ms();
 46→        let window_start = now.saturating_sub(60_000);
 47→
 48→        let mut state = self.state.lock().unwrap_or_else(|e| e.into_inner());
 49→
 50→        // Prune and check global limit.
 51→        while state.global.front().is_some_and(|&t| t < window_start) {
 52→            state.global.pop_front();
 53→        }
 54→        if state.global.len() >= self.global_max as usize {
 55→            return false;
 56→        }
 57→
 58→        // Prune and check per-webhook limit.
 59→        let window = state.per_webhook.entry(webhook_id).or_default();
 60→        while window.front().is_some_and(|&t| t < window_start) {
 61→            window.pop_front();
 62→        }
 63→        if window.len() >= per_webhook_max as usize {
 64→            return false;
 65→        }
 66→
 67→        // Record in both windows atomically.
 68→        window.push_back(now);
 69→        state.global.push_back(now);
 70→
 71→        true
 72→    }
 73→}
 74→
 75→impl Default for WebhookRateLimiter {
 76→    fn default() -> Self {
 77→        Self::new(300) // 300 global requests per minute
 78→    }
 79→}
