 84→
 85→    #[test]
 86→    fn test_basic_rate_limit() {
 87→        let limiter = WebhookRateLimiter::new(100);
 88→        // Should allow requests up to per-webhook max
 89→        for _ in 0..5 {
 90→            assert!(limiter.check(1, 5));
 91→        }
 92→        // 6th request should be rate limited
 93→        assert!(!limiter.check(1, 5));
 94→        // Different webhook should still be allowed
 95→        assert!(limiter.check(2, 5));
 96→    }
 97→
 98→    #[test]
 99→    fn test_global_limit() {
100→        let limiter = WebhookRateLimiter::new(3);
101→        assert!(limiter.check(1, 10));
102→        assert!(limiter.check(2, 10));
103→        assert!(limiter.check(3, 10));
104→        // 4th request should hit global limit
105→        assert!(!limiter.check(4, 10));
106→    }
107→}
