for rel_dir, spec in sorted(SKILL_REQUIRES.items()):
    f = f"crates/skills/src/assets/{rel_dir}/SKILL.md"
    if not os.path.exists(f):
        print(f"SKIP (not found): {f}")
        continue

    with open(f) as fh:
        content = fh.read()

    # Check if requires: already exists
    if '\nrequires:' in content:
        print(f"SKIP (already has requires): {rel_dir}")
        continue

    # Build requires YAML block
    lines = []
    lines.append("requires:")
    if "bins" in spec:
        lines.append("  bins: [" + ", ".join(spec["bins"]) + "]")
    if "any_bins" in spec:
        lines.append("  any_bins: [" + ", ".join(spec["any_bins"]) + "]")
    if "install" in spec:
        lines.append("  install:")
        for inst in spec["install"]:
            lines.append(f"    - kind: {inst['kind']}")
            if "formula" in inst:
                lines.append(f"      formula: {inst['formula']}")
            if "package" in inst:
                lines.append(f"      package: {inst['package']}")
            if "module" in inst:
                lines.append(f"      module: {inst['module']}")
            if inst.get("bins"):
                lines.append(f"      bins: [{', '.join(inst['bins'])}]")
            if inst.get("os"):
                lines.append(f"      os: [{', '.join(inst['os'])}]")
            if inst.get("label"):
                lines.append(f"      label: \"{inst['label']}\"")

    requires_block = "\n".join(lines)

    # Insert before the closing --- of frontmatter
    content_lines = content.split('\n')
    close_idx = None
    for i in range(1, len(content_lines)):
        if content_lines[i].strip() == '---':
            close_idx = i
            break

    if close_idx is None:
        print(f"SKIP (no closing ---): {rel_dir}")
        continue

    new_lines = content_lines[:close_idx] + requires_block.split('\n') + content_lines[close_idx:]

    with open(f, 'w') as fh:
        fh.write('\n'.join(new_lines))

    count += 1
    print(f"UPDATED: {rel_dir}")

print(f"\nTotal updated: {count}")
