import glob, re
from collections import Counter

keys = Counter()
for f in glob.glob("crates/skills/src/assets/**/SKILL.md", recursive=True):
    with open(f) as fh:
        content = fh.read()
    lines = content.split('\n')
    in_fm = False
    for line in lines:
        if line.strip() == '---':
            if not in_fm:
                in_fm = True
                continue
            else:
                break
        if in_fm and re.match(r'^[a-z]', line):
            key = line.split(':')[0].strip()
            keys[key] += 1

for key, count in keys.most_common():
    print(f"  {key}: {count}")
