   1→// ── Skills page (Preact + Signals) ───────────────────────────
   2→// Note: body_html is server-rendered trusted content from SKILL.md
   3→// processed by pulldown-cmark on the Rust gateway side.
   4→
   5→import { computed, signal, useSignal } from "@preact/signals";
   6→import type { VNode } from "preact";
   7→import { render } from "preact";
   8→import { useEffect, useRef } from "preact/hooks";
   9→import { onEvent } from "../events";
  10→import { sendRpc } from "../helpers";
  11→import { updateNavCount } from "../nav-counts";
  12→import { registerPage } from "../router";
  13→import { routes } from "../routes";
  14→import * as S from "../state";
  15→import { ConfirmDialog, requestConfirm } from "../ui";
  16→
  17→// ── Types ────────────────────────────────────────────────────
  18→
  19→interface SkillSummary {
  20→	name: string;
  21→	description?: string;
  22→	source?: string;
  23→	enabled?: boolean;
  24→	protected?: boolean;
  25→	display_name?: string;
  26→	quarantined?: boolean;
  27→	trusted?: boolean;
  28→	drifted?: boolean;
  29→	eligible?: boolean;
  30→}
  31→interface SkillDetail extends SkillSummary {
  32→	body?: string;
  33→	body_html?: string;
  34→	author?: string;
  35→	version?: string;
  36→	homepage?: string;
  37→	source_url?: string;
  38→	commit_sha?: string;
  39→	commit_url?: string;
  40→	commit_age_days?: number;
  41→	compatibility?: string;
  42→	allowed_tools?: string[];
  43→	license?: string;
  44→	license_url?: string;
  45→	missing_bins?: string[];
  46→	install_options?: { label?: string; kind?: string }[];
  47→	requires?: { bins?: string[]; any_bins?: string[] };
  48→	provenance?: { original_source?: string; original_commit_sha?: string; imported_from?: string };
  49→	quarantine_reason?: string;
  50→}
  51→interface RepoSummary {
  52→	source: string;
  53→	skill_count: number;
  54→	enabled_count: number;
  55→	commit_sha?: string;
  56→	quarantined?: boolean;
  57→	drifted?: boolean;
  58→	orphaned?: boolean;
  59→	repo_name?: string;
  60→	provenance?: { original_source?: string; original_commit_sha?: string; imported_from?: string };
  61→	quarantine_reason?: string;
  62→}
  63→interface ToastItem {
  64→	id: number;
  65→	message: string;
  66→	type: string;
  67→}
  68→interface InstallProgress {
  69→	id: string;
  70→	source: string;
  71→	state: string;
  72→}
  73→
  74→const repos = signal<RepoSummary[]>([]);
  75→const enabledSkills = signal<SkillSummary[]>([]);
  76→const loading = signal(false);
  77→const toasts = signal<ToastItem[]>([]);
  78→let toastId = 0;
  79→const installProgresses = signal<InstallProgress[]>([]);
  80→let installProgressId = 0;
  81→
  82→let prefetchPromise: Promise<unknown> | null = null;
  83→function ensurePrefetch(): Promise<unknown> {
  84→	if (!prefetchPromise)
  85→		prefetchPromise = fetch("/api/skills")
  86→			.then((r) => r.json())
  87→			.then((data) => {
  88→				if (data.skills) enabledSkills.value = data.skills;
  89→				if (data.repos) repos.value = data.repos;
  90→				return data;
  91→			})
  92→			.catch(() => null);
  93→	return prefetchPromise;
  94→}
  95→
  96→const skillRepoMap = computed<Record<string, string>>(() => {
  97→	const map: Record<string, string> = {};
  98→	enabledSkills.value.forEach((s) => {
  99→		if (s.source) map[s.name] = s.source;
 100→	});
 101→	return map;
 102→});
 103→
 104→function showToast(message: string, type: string): void {
 105→	const id = ++toastId;
 106→	toasts.value = toasts.value.concat([{ id, message, type }]);
 107→	setTimeout(() => {
 108→		toasts.value = toasts.value.filter((t) => t.id !== id);
 109→	}, 4000);
 110→}
 111→function shortSha(sha: string | null | undefined): string {
 112→	return sha?.slice(0, 12) || "";
 113→}
 114→function startInstallProgress(source: string, id?: string): string {
 115→	const pid = id || `install-${++installProgressId}`;
 116→	if (installProgresses.value.some((p) => p.id === pid)) return pid;
 117→	installProgresses.value = [...installProgresses.value, { id: pid, source: source || "repository", state: "running" }];
 118→	return pid;
 119→}
 120→function stopInstallProgress(id: string, _ok: boolean): void {
 121→	installProgresses.value = installProgresses.value.filter((p) => p.id !== id);
 122→}
 123→
 124→function emergencyDisableAllSkills(): void {
 125→	requestConfirm("Disable all third-party skills now?", { confirmLabel: "Disable All", danger: true }).then((yes) => {
 126→		if (!yes) return;
 127→		sendRpc("skills.emergency_disable", {}).then((res) => {
 128→			if (!res?.ok) {
 129→				showToast(`Emergency disable failed: ${res?.error || "unknown"}`, "error");
 130→				return;
 131→			}
 132→			showToast(`Disabled ${(res.payload as Record<string, number>)?.skills_disabled || 0} skills`, "success");
 133→			fetchAll();
 134→		});
 135→	});
 136→}
 137→
 138→function fetchAll(): void {
 139→	loading.value = true;
 140→	fetch("/api/skills")
 141→		.then((r) => r.json())
 142→		.then((data) => {
 143→			if (data.skills) enabledSkills.value = data.skills;
 144→			if (data.repos) repos.value = data.repos;
 145→			loading.value = false;
 146→			updateNavCount("skills", (data.skills || []).length);
 147→		})
 148→		.catch(() => {
 149→			loading.value = false;
 150→		});
 151→}
 152→
 153→function doInstall(source: string): Promise<void> {
 154→	if (!(source && S.connected)) {
 155→		if (!S.connected) showToast("Not connected to gateway.", "error");
 156→		return Promise.resolve();
 157→	}
 158→	const opId = `skills-install-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
 159→	const pid = startInstallProgress(source, opId);
 160→	return sendRpc("skills.install", { source, op_id: opId }).then((res) => {
 161→		if (res?.ok) {
 162→			const p = (res.payload || {}) as Record<string, unknown[]>;
 163→			showToast(`Installed ${source} (${(p.installed || []).length} skills)`, "success");
 164→			fetchAll();
 165→			stopInstallProgress(pid, true);
 166→		} else {
 167→			showToast(`Failed: ${res?.error || "unknown error"}`, "error");
 168→			stopInstallProgress(pid, false);
 169→		}
 170→	});
 171→}
 172→function doImportBundle(path: string): Promise<void> {
 173→	if (!(path && S.connected)) {
 174→		if (!S.connected) showToast("Not connected.", "error");
 175→		return Promise.resolve();
 176→	}
 177→	return sendRpc("skills.repos.import", { path }).then((res) => {
 178→		if (res?.ok) {
 179→			const p = (res.payload || {}) as Record<string, unknown>;
 180→			showToast(`Imported ${p.repo_name || "bundle"} (${p.skill_count || 0} skills)`, "success");
 181→			fetchAll();
 182→		} else showToast(`Failed: ${res?.error || "unknown"}`, "error");
 183→	});
 184→}
 185→function doExportBundle(source: string, path: string | null): Promise<void> {
 186→	if (!(source && S.connected)) return Promise.resolve();
 187→	const params: Record<string, string> = { source };
 188→	if (path) params.path = path;
 189→	return sendRpc("skills.repos.export", params).then((res) => {
 190→		if (res?.ok) showToast(`Exported ${source}`, "success");
 191→		else showToast(`Failed: ${res?.error || "unknown"}`, "error");
 192→	});
 193→}
 194→export function doUnquarantine(source: string): Promise<void> {
 195→	if (!(source && S.connected)) return Promise.resolve();
 196→	return sendRpc("skills.repos.unquarantine", { source }).then((res) => {
 197→		if (res?.ok) {
 198→			showToast(`Cleared quarantine for ${source}`, "success");
 199→			fetchAll();
 200→		} else showToast(`Failed: ${res?.error || "unknown"}`, "error");
 201→	});
 202→}
 203→function searchSkills(source: string, query: string): Promise<SkillSummary[]> {
 204→	return fetch(`/api/skills/search?source=${encodeURIComponent(source)}&q=${encodeURIComponent(query)}`)
 205→		.then((r) => r.json())
 206→		.then((d) => d.skills || []);
 207→}
