 261→function SecurityWarning(): VNode | null {
 262→	const dismissed = useSignal(!!localStorage.getItem("moltis-skills-warning-dismissed"));
 263→	if (dismissed.value) return null;
 264→	return (
 265→		<div className="skills-warn">
 266→			<div className="skills-warn-title">{"\u26a0\ufe0f"} Skills run code on your machine</div>
 267→			<div>
 268→				Skills are community-authored instructions the agent follows <strong>with your full system privileges</strong>.
 269→			</div>
 270→			<div style={{ marginTop: "6px", color: "var(--success, #4a4)" }}>
 271→				With sandbox mode enabled, execution is isolated.
 272→			</div>
 273→			<div style={{ display: "flex", gap: "8px", marginTop: "8px" }}>
 274→				<button
 275→					onClick={() => {
 276→						localStorage.setItem("moltis-skills-warning-dismissed", "1");
 277→						dismissed.value = true;
 278→					}}
 279→					style={{
 280→						background: "none",
 281→						border: "1px solid var(--border)",
 282→						borderRadius: "var(--radius-sm)",
 283→						fontSize: ".72rem",
 284→						padding: "3px 10px",
 285→						cursor: "pointer",
 286→						color: "var(--muted)",
 287→					}}
 288→				>
 289→					Dismiss
 290→				</button>
 291→				<button className="provider-btn provider-btn-danger provider-btn-sm" onClick={emergencyDisableAllSkills}>
 292→					Disable all
 293→				</button>
 294→			</div>
 295→		</div>
 296→	);
 297→}
