 299→function InstallBox(): VNode {
 300→	const ref = useRef<HTMLInputElement>(null);
 301→	const installing = useSignal(false);
 302→	function go(): void {
 303→		const v = ref.current?.value.trim();
 304→		if (!v) return;
 305→		installing.value = true;
 306→		doInstall(v).then(() => {
 307→			installing.value = false;
 308→			if (ref.current) ref.current.value = "";
 309→		});
 310→	}
 311→	return (
 312→		<div className="skills-install-box">
 313→			<input
 314→				ref={ref}
 315→				type="text"
 316→				placeholder="owner/repo or full URL (e.g. anthropics/skills)"
 317→				className="skills-install-input"
 318→				onKeyDown={(e) => {
 319→					if ((e as KeyboardEvent).key === "Enter") go();
 320→				}}
 321→			/>
 322→			<button className="provider-btn" onClick={go} disabled={installing.value}>
 323→				{installing.value ? "Installing\u2026" : "Install"}
 324→			</button>
 325→		</div>
 326→	);
 327→}
 328→function BundleTransferBox(): VNode {
 329→	const ref = useRef<HTMLInputElement>(null);
 330→	const importing = useSignal(false);
 331→	function go(): void {
 332→		const p = ref.current?.value.trim();
 333→		if (!p) return;
 334→		importing.value = true;
 335→		doImportBundle(p).finally(() => {
 336→			importing.value = false;
 337→		});
 338→	}
 339→	return (
 340→		<div className="skills-install-box">
 341→			<input
 342→				ref={ref}
 343→				type="text"
 344→				placeholder="/path/to/skill-bundle.tar.gz"
 345→				className="skills-install-input"
 346→				onKeyDown={(e) => {
 347→					if ((e as KeyboardEvent).key === "Enter") go();
 348→				}}
 349→			/>
 350→			<button className="provider-btn provider-btn-secondary" onClick={go} disabled={importing.value}>
 351→				{importing.value ? "Importing\u2026" : "Import Bundle"}
 352→			</button>
 353→		</div>
 354→	);
 355→}
