 422→function SkillMetadata({ detail: d }: { detail: SkillDetail }): VNode | null {
 423→	if (!(d.author || d.version || d.homepage || d.source_url || d.commit_sha)) return null;
 424→	return (
 425→		<div
 426→			style={{
 427→				display: "flex",
 428→				alignItems: "center",
 429→				gap: "12px",
 430→				marginBottom: "8px",
 431→				fontSize: ".75rem",
 432→				color: "var(--muted)",
 433→				flexWrap: "wrap",
 434→			}}
 435→		>
 436→			{d.author && <span>Author: {d.author}</span>}
 437→			{d.version && <span>v{d.version}</span>}
 438→			{d.commit_sha && (
 439→				<span>
 440→					Commit: <code>{shortSha(d.commit_sha)}</code>
 441→				</span>
 442→			)}
 443→			{d.homepage && (
 444→				<a
 445→					href={d.homepage}
 446→					target="_blank"
 447→					rel="noopener noreferrer"
 448→					style={{ color: "var(--accent)", textDecoration: "none" }}
 449→				>
 450→					{d.homepage.replace(/^https?:\/\//, "")}
 451→				</a>
 452→			)}
 453→		</div>
 454→	);
 455→}
