 457→function SkillDetailPanel({
 458→	detail: d,
 459→	repoSource,
 460→	onClose,
 461→	onReload,
 462→}: {
 463→	detail: SkillDetail;
 464→	repoSource?: string;
 465→	onClose: () => void;
 466→	onReload?: () => void;
 467→}): VNode | null {
 468→	const actionBusy = useSignal(false);
 469→	const bodyRef = useRef<HTMLDivElement>(null);
 470→	useEffect(() => {
 471→		if (bodyRef.current && d?.body_html) {
 472→			bodyRef.current.textContent = "";
 473→			// Safe: body_html is server-rendered trusted HTML from SKILL.md via pulldown-cmark
 474→			const tpl = document.createElement("template");
 475→			tpl.innerHTML = d.body_html;
 476→			bodyRef.current.appendChild(tpl.content);
 477→			bodyRef.current.querySelectorAll("a").forEach((a) => {
 478→				a.setAttribute("target", "_blank");
 479→				a.setAttribute("rel", "noopener");
 480→			});
 481→		}
 482→	}, [d?.body_html]);
 483→	if (!d) return null;
 484→	const isDisc = d.source === "personal" || d.source === "project";
 485→	function doToggle(): void {
 486→		actionBusy.value = true;
 487→		sendRpc(d.enabled ? "skills.skill.disable" : "skills.skill.enable", { source: repoSource, skill: d.name }).then(
 488→			(r) => {
 489→				actionBusy.value = false;
 490→				if (r?.ok) {
 491→					if (isDisc) onClose();
 492→					fetchAll();
 493→					onReload?.();
 494→				} else showToast(`Failed: ${r?.error || "unknown"}`, "error");
 495→			},
 496→		);
 497→	}
 498→	function onToggle(): void {
 499→		if (!S.connected || actionBusy.value) return;
 500→		if (isDisc && d.protected) {
 501→			showToast(`Protected`, "error");
 502→			return;
 503→		}
 504→		if (isDisc && d.enabled) {
 505→			requestConfirm(`Delete "${d.name}"?`, { confirmLabel: "Delete", danger: true }).then((y) => {
 506→				if (y) doToggle();
 507→			});
 508→			return;
 509→		}
 510→		doToggle();
 511→	}
 512→	return (
 513→		<div className="skills-detail-panel" style={{ display: "block" }}>
 514→			<div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "8px" }}>
 515→				<span
 516→					style={{ fontFamily: "var(--font-mono)", fontSize: ".9rem", fontWeight: 600, color: "var(--text-strong)" }}
 517→				>
 518→					{d.display_name || d.name}
 519→				</span>
 520→				<div style={{ display: "flex", gap: "6px" }}>
 521→					<button
 522→						onClick={onToggle}
 523→						disabled={actionBusy.value}
 524→						className={
 525→							isDisc && d.enabled
 526→								? "provider-btn provider-btn-sm provider-btn-danger"
 527→								: "provider-btn provider-btn-sm provider-btn-secondary"
 528→						}
 529→					>
 530→						{actionBusy.value ? "..." : isDisc && d.enabled ? "Delete" : d.enabled ? "Disable" : "Enable"}
 531→					</button>
 532→					<button
 533→						onClick={onClose}
 534→						style={{ background: "none", border: "none", color: "var(--muted)", cursor: "pointer" }}
 535→					>
 536→						&times;
 537→					</button>
 538→				</div>
 539→			</div>
 540→			<SkillMetadata detail={d} />
 541→			{d.description && <p style={{ margin: "0 0 8px", fontSize: ".82rem" }}>{d.description}</p>}
 542→			{d.body_html && (
 543→				<div
 544→					style={{
 545→						marginTop: "10px",
 546→						border: "1px solid var(--border)",
 547→						borderRadius: "var(--radius-sm)",
 548→						background: "var(--surface2)",
 549→					}}
 550→				>
 551→					<div
 552→						style={{
 553→							padding: "6px 10px",
 554→							borderBottom: "1px solid var(--border)",
 555→							fontSize: ".68rem",
 556→							color: "var(--muted)",
 557→							fontFamily: "var(--font-mono)",
 558→							textTransform: "uppercase",
 559→						}}
 560→					>
 561→						SKILL.md source
 562→					</div>
 563→					<div
 564→						ref={bodyRef}
 565→						className="skill-body-md"
 566→						style={{ padding: "10px", maxHeight: "400px", overflowY: "auto", fontSize: ".8rem", lineHeight: 1.5 }}
 567→					/>
 568→				</div>
 569→			)}
 570→			{!d.body_html && d.body && (
 571→				<div
 572→					style={{
 573→						marginTop: "10px",
 574→						border: "1px solid var(--border)",
 575→						borderRadius: "var(--radius-sm)",
 576→						background: "var(--surface2)",
 577→					}}
 578→				>
 579→					<pre
 580→						style={{
 581→							whiteSpace: "pre-wrap",
 582→							wordBreak: "break-word",
 583→							fontSize: ".78rem",
 584→							fontFamily: "var(--font-mono)",
 585→							margin: 0,
 586→							padding: "10px",
 587→							maxHeight: "400px",
 588→							overflowY: "auto",
 589→						}}
 590→					>
 591→						{d.body}
 592→					</pre>
 593→				</div>
 594→			)}
 595→		</div>
 596→	);
 597→}
