 599→function RepoCard({ repo }: { repo: RepoSummary }): VNode {
 600→	const expanded = useSignal(false);
 601→	const searchQuery = useSignal("");
 602→	const searchResults = useSignal<SkillSummary[]>([]);
 603→	const allSkills = useSignal<SkillSummary[]>([]);
 604→	const searching = useSignal(false);
 605→	const activeDetail = useSignal<SkillDetail | null>(null);
 606→	const detailLoading = useSignal(false);
 607→	const searchTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
 608→	const removingRepo = useSignal(false);
 609→	const exportingRepo = useSignal(false);
 610→	const unquarantiningRepo = useSignal(false);
 611→	const isOrphan = repo.orphaned === true;
 612→	const sourceLabel = isOrphan ? repo.repo_name : repo.source;
 613→	const href = isOrphan ? null : /^https?:\/\//.test(repo.source) ? repo.source : `https://github.com/${repo.source}`;
 614→	function toggle(): void {
 615→		const w = !expanded.value;
 616→		expanded.value = w;
 617→		if (w && !isOrphan && !allSkills.value.length) {
 618→			searching.value = true;
 619→			searchSkills(repo.source, "").then((r) => {
 620→				allSkills.value = r;
 621→				searching.value = false;
 622→			});
 623→		}
 624→	}
 625→	function onSearch(e: Event): void {
 626→		if (isOrphan) return;
 627→		const q = (e.target as HTMLInputElement).value;
 628→		searchQuery.value = q;
 629→		activeDetail.value = null;
 630→		if (searchTimer.current) clearTimeout(searchTimer.current);
 631→		if (!q.trim()) {
 632→			searchResults.value = [];
 633→			return;
 634→		}
 635→		searching.value = true;
 636→		searchTimer.current = setTimeout(() => {
 637→			searchSkills(repo.source, q.trim()).then((r) => {
 638→				searchResults.value = r;
 639→				searching.value = false;
 640→			});
 641→		}, 200);
 642→	}
 643→	function loadDetail(s: SkillSummary): void {
 644→		detailLoading.value = true;
 645→		sendRpc("skills.skill.detail", { source: repo.source, skill: s.name }).then((r) => {
 646→			detailLoading.value = false;
 647→			if (r?.ok) activeDetail.value = r.payload as SkillDetail;
 648→			else showToast(`Failed: ${r?.error || "unknown"}`, "error");
 649→		});
 650→	}
 651→	const displayed = searchQuery.value.trim() ? searchResults.value : allSkills.value;
 652→	return (
 653→		<div className="skills-repo-card">
 654→			<div className="skills-repo-header" onClick={toggle}>
 655→				<div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
 656→					<span style={{ fontSize: ".65rem", color: "var(--muted)", transform: expanded.value ? "rotate(90deg)" : "" }}>
 657→						{"\u25B6"}
 658→					</span>
 659→					{href ? (
 660→						<a
 661→							href={href}
 662→							target="_blank"
 663→							rel="noopener noreferrer"
 664→							onClick={(e) => e.stopPropagation()}
 665→							style={{
 666→								fontFamily: "var(--font-mono)",
 667→								fontSize: ".82rem",
 668→								fontWeight: 500,
 669→								color: "var(--text-strong)",
 670→								textDecoration: "none",
 671→							}}
 672→						>
 673→							{sourceLabel}
 674→						</a>
 675→					) : (
 676→						<span
 677→							style={{
 678→								fontFamily: "var(--font-mono)",
 679→								fontSize: ".82rem",
 680→								fontWeight: 500,
 681→								color: "var(--text-strong)",
 682→							}}
 683→						>
 684→							{sourceLabel}
 685→						</span>
 686→					)}
 687→					<span style={{ fontSize: ".72rem", color: "var(--muted)" }}>
 688→						{repo.enabled_count}/{repo.skill_count} enabled
 689→					</span>
 690→				</div>
 691→				<div style={{ display: "flex", gap: "6px" }}>
 692→					{!isOrphan && (
 693→						<button
 694→							className="provider-btn provider-btn-sm provider-btn-secondary"
 695→							disabled={exportingRepo.value}
 696→							onClick={(e) => {
 697→								e.stopPropagation();
 698→								exportingRepo.value = true;
 699→								doExportBundle(repo.source, null).finally(() => {
 700→									exportingRepo.value = false;
 701→								});
 702→							}}
 703→						>
 704→							{exportingRepo.value ? "Exporting..." : "Export"}
 705→						</button>
 706→					)}
 707→					{repo.quarantined && (
 708→						<button
 709→							className="provider-btn provider-btn-sm provider-btn-secondary"
 710→							disabled={unquarantiningRepo.value}
 711→							onClick={(e) => {
 712→								e.stopPropagation();
 713→								if (!S.connected || unquarantiningRepo.value) return;
 714→								requestConfirm(`Clear quarantine for ${repo.source}?`, {
 715→									confirmLabel: "Clear Quarantine",
 716→								}).then((confirmed) => {
 717→									if (!confirmed) return;
 718→									unquarantiningRepo.value = true;
 719→									doUnquarantine(repo.source).finally(() => {
 720→										unquarantiningRepo.value = false;
 721→									});
 722→								});
 723→							}}
 724→						>
 725→							{unquarantiningRepo.value ? "Clearing..." : "Clear Quarantine"}
 726→						</button>
 727→					)}
 728→					<button
 729→						className="provider-btn provider-btn-sm provider-btn-danger"
 730→						disabled={removingRepo.value}
 731→						onClick={(e) => {
 732→							e.stopPropagation();
 733→							removingRepo.value = true;
 734→							sendRpc("skills.repos.remove", { source: repo.source }).then((r) => {
 735→								removingRepo.value = false;
 736→								if (r?.ok) fetchAll();
 737→								else showToast(`Failed: ${r?.error || "unknown"}`, "error");
 738→							});
 739→						}}
 740→					>
 741→						{removingRepo.value ? "Removing..." : "Remove"}
 742→					</button>
 743→				</div>
 744→			</div>
 745→			{(repo.quarantined || repo.provenance) && expanded.value && (
 746→				<div style={{ padding: "8px 12px", fontSize: ".78rem", color: "var(--muted)" }}>
 747→					{repo.quarantined && (
 748→						<div style={{ marginBottom: "6px", color: "var(--warning, #c77d00)", fontWeight: 600 }}>
 749→							Quarantined{repo.quarantine_reason ? `: ${repo.quarantine_reason}` : ""}
 750→						</div>
 751→					)}
 752→					{repo.provenance?.original_source && (
 753→						<div>
 754→							<strong>Original source:</strong> {repo.provenance.original_source}
 755→						</div>
 756→					)}
 757→					{repo.provenance?.original_commit_sha && (
 758→						<div>
 759→							<strong>Original commit:</strong> <code>{shortSha(repo.provenance.original_commit_sha)}</code>
 760→						</div>
 761→					)}
 762→					{repo.provenance?.imported_from && (
 763→						<div>
 764→							<strong>Imported from:</strong> <code>{repo.provenance.imported_from}</code>
 765→						</div>
 766→					)}
 767→				</div>
 768→			)}
 769→			{expanded.value && (
 770→				<div className="skills-repo-detail" style={{ display: "block" }}>
 771→					<div style={{ marginBottom: "8px" }}>
 772→						<input
 773→							type="text"
 774→							placeholder={`Search skills in ${repo.source}\u2026`}
 775→							value={searchQuery.value}
 776→							disabled={isOrphan}
 777→							onInput={onSearch}
 778→							style={{
 779→								width: "100%",
 780→								padding: "6px 10px",
 781→								border: "1px solid var(--border)",
 782→								borderRadius: "var(--radius-sm)",
 783→								background: "var(--surface)",
 784→								color: "var(--text)",
 785→								fontSize: ".8rem",
 786→								fontFamily: "var(--font-mono)",
 787→								boxSizing: "border-box",
 788→							}}
 789→						/>
 790→					</div>
 791→					{!activeDetail.value && displayed.length > 0 && (
 792→						<div className="skills-browse-list">
 793→							{displayed.map((sk) => (
 794→								<div key={sk.name} className="skills-ac-item" onClick={() => loadDetail(sk)}>
 795→									<span style={{ fontFamily: "var(--font-mono)", fontWeight: 500, color: "var(--text-strong)" }}>
 796→										{sk.display_name || sk.name}
 797→									</span>
 798→									{sk.description && (
 799→										<span style={{ color: "var(--muted)", fontSize: ".72rem", marginLeft: "6px" }}>
 800→											{sk.description}
 801→										</span>
 802→									)}
 803→								</div>
 804→							))}
 805→						</div>
 806→					)}
 807→					{searching.value && !activeDetail.value && (
 808→						<div style={{ padding: "8px", color: "var(--muted)", fontSize: ".78rem" }}>Searching...</div>
 809→					)}
 810→					{activeDetail.value && (
 811→						<SkillDetailPanel
 812→							detail={activeDetail.value}
 813→							repoSource={repo.source}
 814→							onClose={() => {
 815→								activeDetail.value = null;
 816→							}}
 817→							onReload={() => loadDetail({ name: activeDetail.value?.name } as SkillSummary)}
 818→						/>
 819→					)}
 820→				</div>
 821→			)}
 822→		</div>
 823→	);
 824→}
