 854→		sendRpc("skills.skill.disable", { source: map[sk.name] || sk.source, skill: sk.name }).then((r) => {
 855→			pending.value = null;
 856→			if (r?.ok) {
 857→				activeDetail.value = null;
 858→				showToast(isDisc(sk) ? `Deleted ${sk.name}` : `Disabled ${sk.name}`, "success");
 859→				fetchAll();
 860→			} else showToast(`Failed: ${r?.error || "unknown"}`, "error");
 861→		});
 862→	}
