 892→				<table style={{ width: "100%", borderCollapse: "collapse", fontSize: ".82rem" }}>
 893→					<thead>
 894→						<tr style={{ borderBottom: "1px solid var(--border)", background: "var(--surface)" }}>
 895→							<th
 896→								style={{
 897→									textAlign: "left",
 898→									padding: "8px 12px",
 899→									fontWeight: 500,
 900→									color: "var(--muted)",
 901→									fontSize: ".75rem",
 902→									textTransform: "uppercase",
 903→								}}
 904→							>
 905→								Name
 906→							</th>
 907→							<th
 908→								style={{
 909→									textAlign: "left",
 910→									padding: "8px 12px",
 911→									fontWeight: 500,
 912→									color: "var(--muted)",
 913→									fontSize: ".75rem",
 914→									textTransform: "uppercase",
 915→								}}
 916→							>
 917→								Description
 918→							</th>
 919→							<th
 920→								style={{
 921→									textAlign: "left",
 922→									padding: "8px 12px",
 923→									fontWeight: 500,
 924→									color: "var(--muted)",
 925→									fontSize: ".75rem",
 926→									textTransform: "uppercase",
 927→								}}
 928→							>
 929→								Source
 930→							</th>
 931→							<th />
 932→						</tr>
 933→					</thead>
 934→					<tbody>
 935→						{s.map((sk) => (
 936→							<tr
 937→								key={sk.name}
 938→								className="cursor-pointer"
 939→								style={{ borderBottom: "1px solid var(--border)" }}
 940→								onClick={() => loadDetail(sk)}
 941→							>
 942→								<td
 943→									style={{
 944→										padding: "8px 12px",
 945→										fontWeight: 500,
 946→										color: "var(--accent)",
 947→										fontFamily: "var(--font-mono)",
 948→									}}
 949→								>
 950→									{sk.name}
 951→								</td>
