 953→								<td style={{ padding: "8px 12px" }}>
 954→									<span className={sk.source?.includes("/") ? "tier-badge" : "recommended-badge"}>{sk.source}</span>
 955→								</td>
 956→								<td style={{ padding: "8px 12px", textAlign: "right" }}>
 957→									<button
 958→										disabled={(isDisc(sk) && sk.protected === true) || pending.value === sk.name}
 959→										className={
 960→											isDisc(sk)
 961→												? "provider-btn provider-btn-sm provider-btn-danger"
 962→												: "provider-btn provider-btn-sm provider-btn-secondary"
