 967→										}}
 968→									>
 969→										{pending.value === sk.name ? "..." : isDisc(sk) ? "Delete" : "Disable"}
 970→									</button>
 971→								</td>
 972→							</tr>
 973→						))}
 974→					</tbody>
 975→				</table>
 976→			</div>
 977→			{activeDetail.value && (
 978→				<SkillDetailPanel
 979→					detail={activeDetail.value}
