 985→						loadDetail({ name: activeDetail.value?.name, source: activeDetail.value?.source } as SkillSummary)
 986→					}
 987→				/>
 988→			)}
 989→		</div>
 990→	);
 991→}
 992→
 993→function SkillsPageComponent(): VNode {
 994→	useEffect(() => {
 995→		ensurePrefetch().then(() => fetchAll());
 996→		const off = onEvent("skills.install.progress", (p: unknown) => {
