1027→			<SecurityWarning />
1028→			<InstallBox />
1029→			<BundleTransferBox />
1030→			<InstallProgressBar />
1031→			<FeaturedSection />
1032→			<ReposSection />
1033→			{loading.value && !enabledSkills.value.length && !repos.value.length && (
