.settings-alert-error,
.settings-alert-warning {
  display: flex;
  align-items: flex-start;
  gap: 0.6rem;
  padding: 0.75rem 1rem;
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  line-height: 1.4;
  margin-bottom: 0.75rem;
}

/* Simple text alerts (no icon) */
.alert-warning-text,
.alert-info-text,
.alert-error-text {
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.78rem;
  line-height: 1.5;
  color: var(--text);
}

.alert-warning-text {
  background: color-mix(in srgb, var(--warn) 8%, transparent);
  border: 1px solid color-mix(in srgb, var(--warn) 25%, transparent);
}

.alert-info-text {
  background: color-mix(in srgb, var(--accent) 8%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent) 20%, transparent);
}

.alert-error-text {
  background: color-mix(in srgb, var(--error) 6%, transparent);
  border: 1px solid color-mix(in srgb, var(--error) 20%, transparent);
}

.alert-error-text pre {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  line-height: 1.4;
  color: var(--error);
  white-space: pre-wrap;
  word-break: break-word;
  overflow-x: auto;
  max-height: 300px;
  overflow-y: auto;
}

.alert-label-warn { font-weight: 500; color: var(--warn); }
.alert-label-info { font-weight: 500; color: var(--accent); }

/* Max width for form-like sections */
.max-w-form { max-width: 600px; }
.ml-2 { margin-left: 8px; }

.settings-alert-error {
  background: color-mix(in srgb, var(--error) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--error) 30%, transparent);
  color: var(--error);
}

.settings-alert-warning {
  background: color-mix(in srgb, var(--warning, #e6a817) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--warning, #e6a817) 30%, transparent);
  color: var(--warning, #e6a817);
}

.ts-mode-group {
  display: flex;
  gap: 0.4rem;
  margin-top: 0.25rem;
}

.ts-mode-active {
  border-color: var(--accent) !important;
  color: var(--accent) !important;
  background: color-mix(in srgb, var(--accent) 10%, transparent) !important;
}

.ts-mode-configuring {
  border-color: var(--accent) !important;
  color: var(--accent) !important;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.ts-spinner {
  display: inline-block;
  width: 12px;
  height: 12px;
  border: 2px solid color-mix(in srgb, var(--accent) 30%, transparent);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: ts-spin 0.6s linear infinite;
}

@keyframes ts-spin {
  to { transform: rotate(360deg); }
}

.settings-emoji-field {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.35rem;
  position: relative;
}

.settings-emoji-picker {
  position: absolute;
  top: 100%;
  left: 0;
  z-index: 50;
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 2px;
  padding: 8px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-lg);
  max-height: 320px;
  overflow-y: auto;
  margin-top: 4px;
}

.settings-emoji-btn {
  width: 34px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: none;
  cursor: pointer;
}

.settings-emoji-btn:hover {
  background: var(--bg-hover);
}

.settings-emoji-btn.active {
  border-color: var(--accent);
