/* ── Auth Pages (Login / Setup) ── */

.auth-page {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: 100vh;
  padding: 1rem;
  background: var(--bg);
}

.auth-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 2rem 2.5rem;
  width: 360px;
  max-width: 90vw;
  box-shadow: var(--shadow-lg);
}

.auth-title {
  font-size: 1.5rem;
  font-weight: 700;
  text-align: center;
  margin: 0 0 0.25rem;
  color: var(--text-strong);
}

.auth-subtitle {
  text-align: center;
  color: var(--muted);
  font-size: 0.85rem;
  margin: 0 0 1.25rem;
}

.auth-error {
  color: var(--error);
  font-size: 0.8rem;
  margin: 0.5rem 0;
  padding: 0.5rem 0.75rem;
  border: 1px solid color-mix(in srgb, var(--error) 30%, transparent);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--error) 8%, transparent);
}

.auth-divider {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin: 1rem 0;
  color: var(--muted);
  font-size: 0.78rem;
}

.auth-divider::before,
.auth-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--border);
}

.auth-disabled-banner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 6px 16px;
  background: var(--error, #e53935);
  color: #fff;
  font-size: 0.82rem;
  font-weight: 500;
  flex-shrink: 0;
}

.auth-disabled-setup {
  color: #fff;
  text-decoration: underline;
  font-weight: 600;
  white-space: nowrap;
}

.auth-disabled-setup:hover {
  opacity: 0.85;
}

.info-banner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 6px 16px;
  background: var(--accent, #1e88e5);
  color: #fff;
  font-size: 0.82rem;
  font-weight: 500;
  flex-shrink: 0;
}

.branch-banner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 6px 16px;
  background: var(--warn, #f59e0b);
  color: #fff;
  font-size: 0.82rem;
  font-weight: 500;
  flex-shrink: 0;
}

/* ── Tailscale status bar ── */

.info-bar {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--surface2);
  font-size: 0.75rem;
  max-width: 600px;
  white-space: nowrap;
}

.info-bar .info-field {
  display: flex;
  align-items: center;
  gap: 6px;
}

.info-bar .info-label {
  color: var(--muted);
}

.info-bar .info-value {
  color: var(--text);
}

.info-bar .info-value-strong {
  color: var(--text-strong);
  font-weight: 500;
}

.info-bar .info-value-mono {
  color: var(--text);
  font-family: var(--font-mono);
}

.info-bar .info-version {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: var(--muted);
}

/* ── Microphone Button ── */

.mic-btn.recording {
  background: var(--error) !important;
  border-color: var(--error) !important;
  color: #fff !important;
  animation: mic-pulse 1s infinite;
}

.mic-btn.starting {
  opacity: 0.85;
  cursor: progress;
}

.mic-btn.transcribing {
  opacity: 0.7;
  cursor: wait;
}

@keyframes mic-pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.05); }
}

/* ── Toggle Switch ── */

.toggle-switch {
  position: relative;
  display: inline-block;
  width: 40px;
  height: 22px;
  flex-shrink: 0;
}

.toggle-switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.toggle-slider {
  position: absolute;
  cursor: pointer;
  inset: 0;
  background: var(--surface2);
  transition: 0.2s;
  border-radius: 22px;
  border: 1px solid var(--border);
}

.toggle-slider::before {
  position: absolute;
  content: "";
  height: 16px;
  width: 16px;
  left: 2px;
  bottom: 2px;
  background: var(--text);
  transition: 0.2s;
  border-radius: 50%;
}

.toggle-switch input:checked + .toggle-slider {
  background: var(--accent);
  border-color: var(--accent);
}

.toggle-switch input:checked + .toggle-slider::before {
  transform: translateX(18px);
  background: white;
}

.toggle-switch input:disabled + .toggle-slider {
  opacity: 0.5;
  cursor: not-allowed;
}

