 60→function formatOwnerDisplayId(ownerId: string, ownerDisplaySecret?: string) {
 61→  const hasSecret = ownerDisplaySecret?.trim();
 62→  const digest = hasSecret
 63→    ? createHmac("sha256", hasSecret).update(ownerId).digest("hex")
 64→    : createHash("sha256").update(ownerId).digest("hex");
 65→  return digest.slice(0, 12);
 66→}
