 30→/**
 31→ * Replace the user's home directory prefix with `~` in skill file paths
 32→ * to reduce system prompt token usage. Models understand `~` expansion,
 33→ * and the read tool resolves `~` to the home directory.
 34→ *
 35→ * Example: `/Users/alice/.bun/.../skills/github/SKILL.md`
 36→ *       → `~/.bun/.../skills/github/SKILL.md`
 37→ *
 38→ * Saves ~5–6 tokens per skill path × N skills ≈ 400–600 tokens total.
 39→ */
 40→function compactSkillPaths(skills: Skill[]): Skill[] {
 41→  const home = os.homedir();
 42→  if (!home) return skills;
 43→  const prefix = home.endsWith(path.sep) ? home : home + path.sep;
 44→  return skills.map((s) => ({
 45→    ...s,
 46→    filePath: s.filePath.startsWith(prefix) ? "~/" + s.filePath.slice(prefix.length) : s.filePath,
 47→  }));
 48→}
