 85→const SKILL_COMMAND_MAX_LENGTH = 32;
 86→const SKILL_COMMAND_FALLBACK = "skill";
 87→// Discord command descriptions must be ≤100 characters
 88→const SKILL_COMMAND_DESCRIPTION_MAX_LENGTH = 100;
 89→
 90→const DEFAULT_MAX_CANDIDATES_PER_ROOT = 300;
 91→const DEFAULT_MAX_SKILLS_LOADED_PER_SOURCE = 200;
 92→const DEFAULT_MAX_SKILLS_IN_PROMPT = 150;
