 96→function sanitizeSkillCommandName(raw: string): string {
 97→  const normalized = raw
 98→    .toLowerCase()
 99→    .replace(/[^a-z0-9_]+/g, "_")
100→    .replace(/_+/g, "_")
101→    .replace(/^_+|_+$/g, "");
102→  const trimmed = normalized.slice(0, SKILL_COMMAND_MAX_LENGTH);
103→  return trimmed || SKILL_COMMAND_FALLBACK;
104→}
105→
106→function resolveUniqueSkillCommandName(base: string, used: Set<string>): string {
107→  const normalizedBase = base.toLowerCase();
108→  if (!used.has(normalizedBase)) {
109→    return base;
110→  }
111→  for (let index = 2; index < 1000; index += 1) {
112→    const suffix = `_${index}`;
113→    const maxBaseLength = Math.max(1, SKILL_COMMAND_MAX_LENGTH - suffix.length);
114→    const trimmedBase = base.slice(0, maxBaseLength);
115→    const candidate = `${trimmedBase}${suffix}`;
116→    const candidateKey = candidate.toLowerCase();
117→    if (!used.has(candidateKey)) {
118→      return candidate;
119→    }
120→  }
121→  const fallback = `${base.slice(0, Math.max(1, SKILL_COMMAND_MAX_LENGTH - 2))}_x`;
122→  return fallback;
123→}
