145→function listChildDirectories(dir: string): string[] {
146→  try {
147→    const entries = fs.readdirSync(dir, { withFileTypes: true });
148→    const dirs: string[] = [];
149→    for (const entry of entries) {
150→      if (entry.name.startsWith(".")) continue;
151→      if (entry.name === "node_modules") continue;
152→      const fullPath = path.join(dir, entry.name);
153→      if (entry.isDirectory()) {
154→        dirs.push(entry.name);
155→        continue;
156→      }
157→      if (entry.isSymbolicLink()) {
158→        try {
159→          if (fs.statSync(fullPath).isDirectory()) {
160→            dirs.push(entry.name);
161→          }
162→        } catch {
163→          // ignore broken symlinks
164→        }
165→      }
166→    }
167→    return dirs;
168→  } catch {
169→    return [];
170→  }
171→}
172→
173→function tryRealpath(filePath: string): string | null {
174→  try {
175→    return fs.realpathSync(filePath);
176→  } catch {
177→    return null;
178→  }
179→}
