181→function warnEscapedSkillPath(params: {
182→  source: string;
183→  rootDir: string;
184→  candidatePath: string;
185→  candidateRealPath: string;
186→}) {
187→  skillsLogger.warn("Skipping skill path that resolves outside its configured root.", {
188→    source: params.source,
189→    rootDir: params.rootDir,
190→    path: params.candidatePath,
191→    realPath: params.candidateRealPath,
192→  });
193→}
194→
195→function resolveContainedSkillPath(params: {
196→  source: string;
197→  rootDir: string;
198→  rootRealPath: string;
199→  candidatePath: string;
200→}): string | null {
201→  const candidateRealPath = tryRealpath(params.candidatePath);
202→  if (!candidateRealPath) {
203→    return null;
204→  }
205→  if (isPathInside(params.rootRealPath, candidateRealPath)) {
206→    return candidateRealPath;
207→  }
208→  warnEscapedSkillPath({
209→    source: params.source,
210→    rootDir: params.rootDir,
211→    candidatePath: path.resolve(params.candidatePath),
212→    candidateRealPath,
213→  });
214→  return null;
215→}
216→
217→function filterLoadedSkillsInsideRoot(params: {
218→  skills: Skill[];
219→  source: string;
220→  rootDir: string;
221→  rootRealPath: string;
222→}): Skill[] {
223→  return params.skills.filter((skill) => {
224→    const baseDirRealPath = resolveContainedSkillPath({
225→      source: params.source,
226→      rootDir: params.rootDir,
227→      rootRealPath: params.rootRealPath,
228→      candidatePath: skill.baseDir,
229→    });
230→    if (!baseDirRealPath) {
231→      return false;
232→    }
233→    const skillFileRealPath = resolveContainedSkillPath({
234→      source: params.source,
235→      rootDir: params.rootDir,
236→      rootRealPath: params.rootRealPath,
237→      candidatePath: skill.filePath,
238→    });
239→    return Boolean(skillFileRealPath);
240→  });
241→}
