243→function resolveNestedSkillsRoot(
244→  dir: string,
245→  opts?: {
246→    maxEntriesToScan?: number;
247→  },
248→): { baseDir: string; note?: string } {
249→  const nested = path.join(dir, "skills");
250→  try {
251→    if (!fs.existsSync(nested) || !fs.statSync(nested).isDirectory()) {
252→      return { baseDir: dir };
253→    }
254→  } catch {
255→    return { baseDir: dir };
256→  }
257→
258→  // Heuristic: if `dir/skills/*/SKILL.md` exists for any entry, treat `dir/skills` as the real root.
259→  // Note: don't stop at 25, but keep a cap to avoid pathological scans.
260→  const nestedDirs = listChildDirectories(nested);
261→  const scanLimit = Math.max(0, opts?.maxEntriesToScan ?? 100);
262→  const toScan = scanLimit === 0 ? [] : nestedDirs.slice(0, Math.min(nestedDirs.length, scanLimit));
263→
264→  for (const name of toScan) {
265→    const skillMd = path.join(nested, name, "SKILL.md");
266→    if (fs.existsSync(skillMd)) {
267→      return { baseDir: nested, note: `Detected nested skills root at ${nested}` };
268→    }
269→  }
270→  return { baseDir: dir };
271→}
272→
273→function unwrapLoadedSkills(loaded: unknown): Skill[] {
274→  if (Array.isArray(loaded)) {
275→    return loaded as Skill[];
276→  }
277→  if (loaded && typeof loaded === "object" && "skills" in loaded) {
278→    const skills = (loaded as { skills?: unknown }).skills;
279→    if (Array.isArray(skills)) {
280→      return skills as Skill[];
281→    }
282→  }
283→  return [];
284→}
