286→function loadSkillEntries(
287→  workspaceDir: string,
288→  opts?: {
289→    config?: OpenClawConfig;
290→    managedSkillsDir?: string;
291→    bundledSkillsDir?: string;
292→  },
293→): SkillEntry[] {
294→  const limits = resolveSkillsLimits(opts?.config);
295→
296→  const loadSkills = (params: { dir: string; source: string }): Skill[] => {
297→    const rootDir = path.resolve(params.dir);
298→    const rootRealPath = tryRealpath(rootDir) ?? rootDir;
299→    const resolved = resolveNestedSkillsRoot(params.dir, {
300→      maxEntriesToScan: limits.maxCandidatesPerRoot,
301→    });
302→    const baseDir = resolved.baseDir;
303→    const baseDirRealPath = resolveContainedSkillPath({
304→      source: params.source,
305→      rootDir,
306→      rootRealPath,
307→      candidatePath: baseDir,
308→    });
309→    if (!baseDirRealPath) {
310→      return [];
311→    }
312→
313→    // If the root itself is a skill directory, just load it directly (but enforce size cap).
314→    const rootSkillMd = path.join(baseDir, "SKILL.md");
315→    if (fs.existsSync(rootSkillMd)) {
316→      const rootSkillRealPath = resolveContainedSkillPath({
317→        source: params.source,
318→        rootDir,
319→        rootRealPath: baseDirRealPath,
320→        candidatePath: rootSkillMd,
321→      });
322→      if (!rootSkillRealPath) {
323→        return [];
324→      }
325→      try {
326→        const size = fs.statSync(rootSkillRealPath).size;
327→        if (size > limits.maxSkillFileBytes) {
328→          skillsLogger.warn("Skipping skills root due to oversized SKILL.md.", {
329→            dir: baseDir,
330→            filePath: rootSkillMd,
331→            size,
332→            maxSkillFileBytes: limits.maxSkillFileBytes,
333→          });
334→          return [];
335→        }
336→      } catch {
337→        return [];
338→      }
339→
340→      const loaded = loadSkillsFromDirSafe({
341→        dir: baseDir,
342→        source: params.source,
343→        maxBytes: limits.maxSkillFileBytes,
344→      });
345→      return filterLoadedSkillsInsideRoot({
346→        skills: unwrapLoadedSkills(loaded),
347→        source: params.source,
348→        rootDir,
349→        rootRealPath: baseDirRealPath,
350→      });
351→    }
352→
353→    const childDirs = listChildDirectories(baseDir);
354→    const suspicious = childDirs.length > limits.maxCandidatesPerRoot;
355→
356→    const maxCandidates = Math.max(0, limits.maxSkillsLoadedPerSource);
357→    const limitedChildren = childDirs.slice().sort().slice(0, maxCandidates);
358→
359→    if (suspicious) {
360→      skillsLogger.warn("Skills root looks suspiciously large, truncating discovery.", {
361→        dir: params.dir,
362→        baseDir,
363→        childDirCount: childDirs.length,
364→        maxCandidatesPerRoot: limits.maxCandidatesPerRoot,
365→        maxSkillsLoadedPerSource: limits.maxSkillsLoadedPerSource,
366→      });
367→    } else if (childDirs.length > maxCandidates) {
368→      skillsLogger.warn("Skills root has many entries, truncating discovery.", {
369→        dir: params.dir,
370→        baseDir,
371→        childDirCount: childDirs.length,
372→        maxSkillsLoadedPerSource: limits.maxSkillsLoadedPerSource,
373→      });
374→    }
375→
376→    const loadedSkills: Skill[] = [];
377→
378→    // Only consider immediate subfolders that look like skills (have SKILL.md) and are under size cap.
379→    for (const name of limitedChildren) {
380→      const skillDir = path.join(baseDir, name);
381→      const skillDirRealPath = resolveContainedSkillPath({
382→        source: params.source,
383→        rootDir,
384→        rootRealPath: baseDirRealPath,
385→        candidatePath: skillDir,
386→      });
387→      if (!skillDirRealPath) {
388→        continue;
389→      }
390→      const skillMd = path.join(skillDir, "SKILL.md");
391→      if (!fs.existsSync(skillMd)) {
392→        continue;
393→      }
394→      const skillMdRealPath = resolveContainedSkillPath({
395→        source: params.source,
396→        rootDir,
397→        rootRealPath: baseDirRealPath,
398→        candidatePath: skillMd,
399→      });
400→      if (!skillMdRealPath) {

400→      if (!skillMdRealPath) {
401→        continue;
402→      }
403→      try {
404→        const size = fs.statSync(skillMdRealPath).size;
405→        if (size > limits.maxSkillFileBytes) {
406→          skillsLogger.warn("Skipping skill due to oversized SKILL.md.", {
407→            skill: name,
408→            filePath: skillMd,
409→            size,
410→            maxSkillFileBytes: limits.maxSkillFileBytes,
411→          });
412→          continue;
413→        }
414→      } catch {
415→        continue;
416→      }
417→
418→      const loaded = loadSkillsFromDirSafe({
419→        dir: skillDir,
420→        source: params.source,
421→        maxBytes: limits.maxSkillFileBytes,
422→      });
423→      loadedSkills.push(
424→        ...filterLoadedSkillsInsideRoot({
425→          skills: unwrapLoadedSkills(loaded),
426→          source: params.source,
427→          rootDir,
428→          rootRealPath: baseDirRealPath,
429→        }),
430→      );
431→
432→      if (loadedSkills.length >= limits.maxSkillsLoadedPerSource) {
433→        break;
434→      }
435→    }
436→
437→    if (loadedSkills.length > limits.maxSkillsLoadedPerSource) {
438→      return loadedSkills
439→        .slice()
440→        .sort((a, b) => a.name.localeCompare(b.name))
441→        .slice(0, limits.maxSkillsLoadedPerSource);
442→    }
443→
444→    return loadedSkills;
445→  };
446→
447→  const managedSkillsDir = opts?.managedSkillsDir ?? path.join(CONFIG_DIR, "skills");
448→  const workspaceSkillsDir = path.resolve(workspaceDir, "skills");
449→  const bundledSkillsDir = opts?.bundledSkillsDir ?? resolveBundledSkillsDir();
450→  const extraDirsRaw = opts?.config?.skills?.load?.extraDirs ?? [];
451→  const extraDirs = extraDirsRaw
452→    .map((d) => (typeof d === "string" ? d.trim() : ""))
453→    .filter(Boolean);
454→  const pluginSkillDirs = resolvePluginSkillDirs({
455→    workspaceDir,
456→    config: opts?.config,
457→  });
458→  const mergedExtraDirs = [...extraDirs, ...pluginSkillDirs];
459→
460→  const bundledSkills = bundledSkillsDir
461→    ? loadSkills({
462→        dir: bundledSkillsDir,
463→        source: "openclaw-bundled",
464→      })
465→    : [];
466→  const extraSkills = mergedExtraDirs.flatMap((dir) => {
467→    const resolved = resolveUserPath(dir);
468→    return loadSkills({
469→      dir: resolved,
470→      source: "openclaw-extra",
471→    });
472→  });
473→  const managedSkills = loadSkills({
474→    dir: managedSkillsDir,
475→    source: "openclaw-managed",
476→  });
477→  const personalAgentsSkillsDir = path.resolve(os.homedir(), ".agents", "skills");
478→  const personalAgentsSkills = loadSkills({
479→    dir: personalAgentsSkillsDir,
480→    source: "agents-skills-personal",
481→  });
482→  const projectAgentsSkillsDir = path.resolve(workspaceDir, ".agents", "skills");
483→  const projectAgentsSkills = loadSkills({
484→    dir: projectAgentsSkillsDir,
485→    source: "agents-skills-project",
486→  });
487→  const workspaceSkills = loadSkills({
488→    dir: workspaceSkillsDir,
489→    source: "openclaw-workspace",
490→  });
491→
492→  const merged = new Map<string, Skill>();
493→  // Precedence: extra < bundled < managed < agents-skills-personal < agents-skills-project < workspace
494→  for (const skill of extraSkills) {
495→    merged.set(skill.name, skill);
496→  }
497→  for (const skill of bundledSkills) {
498→    merged.set(skill.name, skill);
499→  }
500→  for (const skill of managedSkills) {
501→    merged.set(skill.name, skill);
502→  }
503→  for (const skill of personalAgentsSkills) {
504→    merged.set(skill.name, skill);
505→  }
506→  for (const skill of projectAgentsSkills) {
507→    merged.set(skill.name, skill);
508→  }
509→  for (const skill of workspaceSkills) {
510→    merged.set(skill.name, skill);
511→  }
512→
513→  const skillEntries: SkillEntry[] = Array.from(merged.values()).map((skill) => {
514→    const frontmatter =
515→      readSkillFrontmatterSafe({
516→        rootDir: skill.baseDir,
517→        filePath: skill.filePath,
518→        maxBytes: limits.maxSkillFileBytes,
519→      }) ?? ({} as ParsedSkillFrontmatter);
520→    return {
521→      skill,
522→      frontmatter,
523→      metadata: resolveOpenClawMetadata(frontmatter),
524→      invocation: resolveSkillInvocationPolicy(frontmatter),
525→    };
526→  });
527→  return skillEntries;
528→}
