530→function escapeXml(str: string): string {
531→  return str
532→    .replace(/&/g, "&amp;")
533→    .replace(/</g, "&lt;")
534→    .replace(/>/g, "&gt;")
535→    .replace(/"/g, "&quot;")
536→    .replace(/'/g, "&apos;");
537→}
538→
539→/**
540→ * Compact skill catalog: name + location only (no description).
541→ * Used as a fallback when the full format exceeds the char budget,
542→ * preserving awareness of all skills before resorting to dropping.
543→ */
544→export function formatSkillsCompact(skills: Skill[]): string {
545→  const visible = skills.filter((s) => !s.disableModelInvocation);
546→  if (visible.length === 0) return "";
547→  const lines = [
548→    "\n\nThe following skills provide specialized instructions for specific tasks.",
549→    "Use the read tool to load a skill's file when the task matches its name.",
550→    "When a skill file references a relative path, resolve it against the skill directory (parent of SKILL.md / dirname of the path) and use that absolute path in tool commands.",
551→    "",
552→    "<available_skills>",
553→  ];
554→  for (const skill of visible) {
555→    lines.push("  <skill>");
556→    lines.push(`    <name>${escapeXml(skill.name)}</name>`);
557→    lines.push(`    <location>${escapeXml(skill.filePath)}</location>`);
558→    lines.push("  </skill>");
559→  }
560→  lines.push("</available_skills>");
561→  return lines.join("\n");
562→}
563→
564→// Budget reserved for the compact-mode warning line prepended by the caller.
565→const COMPACT_WARNING_OVERHEAD = 150;
566→
567→function applySkillsPromptLimits(params: { skills: Skill[]; config?: OpenClawConfig }): {
568→  skillsForPrompt: Skill[];
569→  truncated: boolean;
570→  compact: boolean;
571→} {
572→  const limits = resolveSkillsLimits(params.config);
573→  const total = params.skills.length;
574→  const byCount = params.skills.slice(0, Math.max(0, limits.maxSkillsInPrompt));
575→
576→  let skillsForPrompt = byCount;
577→  let truncated = total > byCount.length;
578→  let compact = false;
579→
580→  const fitsFull = (skills: Skill[]): boolean =>
581→    formatSkillsForPrompt(skills).length <= limits.maxSkillsPromptChars;
582→
583→  // Reserve space for the warning line the caller prepends in compact mode.
584→  const compactBudget = limits.maxSkillsPromptChars - COMPACT_WARNING_OVERHEAD;
585→  const fitsCompact = (skills: Skill[]): boolean =>
586→    formatSkillsCompact(skills).length <= compactBudget;
587→
588→  if (!fitsFull(skillsForPrompt)) {
589→    // Full format exceeds budget. Try compact (name + location, no description)
590→    // to preserve awareness of all skills before dropping any.
591→    if (fitsCompact(skillsForPrompt)) {
592→      compact = true;
593→      // No skills dropped — only format downgraded. Preserve existing truncated state.
594→    } else {
595→      // Compact still too large — binary search the largest prefix that fits.
596→      compact = true;
597→      let lo = 0;
598→      let hi = skillsForPrompt.length;
599→      while (lo < hi) {
600→        const mid = Math.ceil((lo + hi) / 2);
601→        if (fitsCompact(skillsForPrompt.slice(0, mid))) {
602→          lo = mid;
603→        } else {
604→          hi = mid - 1;
605→        }
606→      }
607→      skillsForPrompt = skillsForPrompt.slice(0, lo);
608→      truncated = true;
609→    }
610→  }
611→
612→  return { skillsForPrompt, truncated, compact };
613→}
