634→export function buildWorkspaceSkillsPrompt(
635→  workspaceDir: string,
636→  opts?: WorkspaceSkillBuildOptions,
637→): string {
638→  return resolveWorkspaceSkillPromptState(workspaceDir, opts).prompt;
