641→type WorkspaceSkillBuildOptions = {
642→  config?: OpenClawConfig;
643→  managedSkillsDir?: string;
644→  bundledSkillsDir?: string;
645→  entries?: SkillEntry[];
646→  /** If provided, only include skills with these names */
647→  skillFilter?: string[];
648→  eligibility?: SkillEligibilityContext;
649→};
