651→function resolveWorkspaceSkillPromptState(
652→  workspaceDir: string,
653→  opts?: WorkspaceSkillBuildOptions,
654→): {
655→  eligible: SkillEntry[];
656→  prompt: string;
657→  resolvedSkills: Skill[];
658→} {
659→  const skillEntries = opts?.entries ?? loadSkillEntries(workspaceDir, opts);
660→  const eligible = filterSkillEntries(
661→    skillEntries,
662→    opts?.config,
663→    opts?.skillFilter,
664→    opts?.eligibility,
665→  );
666→  const promptEntries = eligible.filter(
667→    (entry) => entry.invocation?.disableModelInvocation !== true,
668→  );
669→  const remoteNote = opts?.eligibility?.remote?.note?.trim();
670→  const resolvedSkills = promptEntries.map((entry) => entry.skill);
671→  // Derive prompt-facing skills with compacted paths (e.g. ~/...) once.
672→  // Budget checks and final render both use this same representation so the
673→  // tier decision is based on the exact strings that end up in the prompt.
674→  // resolvedSkills keeps canonical paths for snapshot / runtime consumers.
675→  const promptSkills = compactSkillPaths(resolvedSkills);
676→  const { skillsForPrompt, truncated, compact } = applySkillsPromptLimits({
677→    skills: promptSkills,
678→    config: opts?.config,
679→  });
680→  const truncationNote = truncated
681→    ? `⚠️ Skills truncated: included ${skillsForPrompt.length} of ${resolvedSkills.length}${compact ? " (compact format, descriptions omitted)" : ""}. Run \`openclaw skills check\` to audit.`
682→    : compact
683→      ? `⚠️ Skills catalog using compact format (descriptions omitted). Run \`openclaw skills check\` to audit.`
684→      : "";
685→  const prompt = [
686→    remoteNote,
687→    truncationNote,
688→    compact ? formatSkillsCompact(skillsForPrompt) : formatSkillsForPrompt(skillsForPrompt),
689→  ]
690→    .filter(Boolean)
691→    .join("\n");
692→  return { eligible, prompt, resolvedSkills };
693→}
