726→function resolveUniqueSyncedSkillDirName(base: string, used: Set<string>): string {
727→  if (!used.has(base)) {
728→    used.add(base);
729→    return base;
730→  }
731→  for (let index = 2; index < 10_000; index += 1) {
732→    const candidate = `${base}-${index}`;
733→    if (!used.has(candidate)) {
734→      used.add(candidate);
735→      return candidate;
736→    }
737→  }
738→  let fallbackIndex = 10_000;
739→  let fallback = `${base}-${fallbackIndex}`;
740→  while (used.has(fallback)) {
741→    fallbackIndex += 1;
742→    fallback = `${base}-${fallbackIndex}`;
743→  }
744→  used.add(fallback);
745→  return fallback;
746→}
