748→function resolveSyncedSkillDestinationPath(params: {
749→  targetSkillsDir: string;
750→  entry: SkillEntry;
751→  usedDirNames: Set<string>;
752→}): string | null {
753→  const sourceDirName = path.basename(params.entry.skill.baseDir).trim();
754→  if (!sourceDirName || sourceDirName === "." || sourceDirName === "..") {
755→    return null;
756→  }
757→  const uniqueDirName = resolveUniqueSyncedSkillDirName(sourceDirName, params.usedDirNames);
758→  return resolveSandboxPath({
759→    filePath: uniqueDirName,
760→    cwd: params.targetSkillsDir,
761→    root: params.targetSkillsDir,
762→  }).resolved;
763→}
