830→export function buildWorkspaceSkillCommandSpecs(
831→  workspaceDir: string,
832→  opts?: {
833→    config?: OpenClawConfig;
834→    managedSkillsDir?: string;
835→    bundledSkillsDir?: string;
836→    entries?: SkillEntry[];
837→    skillFilter?: string[];
838→    eligibility?: SkillEligibilityContext;
839→    reservedNames?: Set<string>;
840→  },
841→): SkillCommandSpec[] {
842→  const skillEntries = opts?.entries ?? loadSkillEntries(workspaceDir, opts);
843→  const eligible = filterSkillEntries(
844→    skillEntries,
845→    opts?.config,
846→    opts?.skillFilter,
847→    opts?.eligibility,
848→  );
849→  const userInvocable = eligible.filter((entry) => entry.invocation?.userInvocable !== false);
850→  const used = new Set<string>();
851→  for (const reserved of opts?.reservedNames ?? []) {
852→    used.add(reserved.toLowerCase());
853→  }
854→
855→  const specs: SkillCommandSpec[] = [];
856→  for (const entry of userInvocable) {
857→    const rawName = entry.skill.name;
858→    const base = sanitizeSkillCommandName(rawName);
859→    if (base !== rawName) {
860→      debugSkillCommandOnce(
861→        `sanitize:${rawName}:${base}`,
862→        `Sanitized skill command name "${rawName}" to "/${base}".`,
863→        { rawName, sanitized: `/${base}` },
864→      );
865→    }
866→    const unique = resolveUniqueSkillCommandName(base, used);
867→    if (unique !== base) {
868→      debugSkillCommandOnce(
869→        `dedupe:${rawName}:${unique}`,
870→        `De-duplicated skill command name for "${rawName}" to "/${unique}".`,
871→        { rawName, deduped: `/${unique}` },
872→      );
873→    }
874→    used.add(unique.toLowerCase());
875→    const rawDescription = entry.skill.description?.trim() || rawName;
876→    const description =
877→      rawDescription.length > SKILL_COMMAND_DESCRIPTION_MAX_LENGTH
878→        ? rawDescription.slice(0, SKILL_COMMAND_DESCRIPTION_MAX_LENGTH - 1) + "…"
879→        : rawDescription;
880→    const dispatch = (() => {
881→      const kindRaw = (
882→        entry.frontmatter?.["command-dispatch"] ??
883→        entry.frontmatter?.["command_dispatch"] ??
884→        ""
885→      )
886→        .trim()
887→        .toLowerCase();
888→      if (!kindRaw) {
889→        return undefined;
890→      }
891→      if (kindRaw !== "tool") {
892→        return undefined;
893→      }
894→
895→      const toolName = (
896→        entry.frontmatter?.["command-tool"] ??
897→        entry.frontmatter?.["command_tool"] ??
898→        ""
899→      ).trim();
900→      if (!toolName) {
901→        debugSkillCommandOnce(
902→          `dispatch:missingTool:${rawName}`,
903→          `Skill command "/${unique}" requested tool dispatch but did not provide command-tool. Ignoring dispatch.`,
904→          { skillName: rawName, command: unique },
905→        );
906→        return undefined;
907→      }
908→
909→      const argModeRaw = (
910→        entry.frontmatter?.["command-arg-mode"] ??
911→        entry.frontmatter?.["command_arg_mode"] ??
912→        ""
913→      )
914→        .trim()
915→        .toLowerCase();
916→      const argMode = !argModeRaw || argModeRaw === "raw" ? "raw" : null;
917→      if (!argMode) {
918→        debugSkillCommandOnce(
919→          `dispatch:badArgMode:${rawName}:${argModeRaw}`,
920→          `Skill command "/${unique}" requested tool dispatch but has unknown command-arg-mode. Falling back to raw.`,
921→          { skillName: rawName, command: unique, argMode: argModeRaw },
922→        );
923→      }
924→
925→      return { kind: "tool", toolName, argMode: "raw" } as const;
926→    })();
927→
928→    specs.push({
929→      name: unique,
930→      skillName: rawName,
931→      description,
932→      ...(dispatch ? { dispatch } : {}),
933→    });
934→  }
935→
936→  const bundleCommands = loadEnabledClaudeBundleCommands({
937→    workspaceDir,
938→    cfg: opts?.config,
939→  });
940→  for (const entry of bundleCommands) {
941→    const base = sanitizeSkillCommandName(entry.rawName);
942→    if (base !== entry.rawName) {
943→      debugSkillCommandOnce(
944→        `bundle-sanitize:${entry.rawName}:${base}`,
945→        `Sanitized bundle command name "${entry.rawName}" to "/${base}".`,
946→        { rawName: entry.rawName, sanitized: `/${base}` },
947→      );
948→    }
949→    const unique = resolveUniqueSkillCommandName(base, used);
950→    if (unique !== base) {
951→      debugSkillCommandOnce(
952→        `bundle-dedupe:${entry.rawName}:${unique}`,
953→        `De-duplicated bundle command name for "${entry.rawName}" to "/${unique}".`,
954→        { rawName: entry.rawName, deduped: `/${unique}` },
955→      );
956→    }
957→    used.add(unique.toLowerCase());
958→    const description =
959→      entry.description.length > SKILL_COMMAND_DESCRIPTION_MAX_LENGTH
960→        ? entry.description.slice(0, SKILL_COMMAND_DESCRIPTION_MAX_LENGTH - 1) + "…"
961→        : entry.description;
962→    specs.push({
963→      name: unique,
964→      skillName: entry.rawName,
965→      description,
966→      promptTemplate: entry.promptTemplate,
967→      sourceFilePath: entry.sourceFilePath,
968→    });
969→  }
970→  return specs;
971→}
