 1→import { buildHistoryContextFromEntries, type HistoryEntry } from "../auto-reply/reply/history.js";
 2→import { extractTextFromChatContent } from "../shared/chat-content.js";
 3→
 4→export type ConversationEntry = {
 5→  role: "user" | "assistant" | "tool";
 6→  entry: HistoryEntry;
 7→};
 8→
 9→/**
10→ * Coerce body to string. Handles cases where body is a content array
11→ * (e.g. [{type:"text", text:"hello"}]) that would serialize as
12→ * [object Object] if used directly in a template literal.
13→ */
14→function safeBody(body: unknown): string {
15→  if (typeof body === "string") {
16→    return body;
17→  }
18→  return extractTextFromChatContent(body) ?? "";
19→}
20→
21→export function buildAgentMessageFromConversationEntries(entries: ConversationEntry[]): string {
22→  if (entries.length === 0) {
23→    return "";
24→  }
25→
26→  // Prefer the last user/tool entry as "current message" so the agent responds to
27→  // the latest user input or tool output, not the assistant's previous message.
28→  let currentIndex = -1;
29→  for (let i = entries.length - 1; i >= 0; i -= 1) {
30→    const role = entries[i]?.role;
31→    if (role === "user" || role === "tool") {
32→      currentIndex = i;
33→      break;
34→    }
35→  }
36→  if (currentIndex < 0) {
37→    currentIndex = entries.length - 1;
38→  }
39→
40→  const currentEntry = entries[currentIndex]?.entry;
41→  if (!currentEntry) {
42→    return "";
43→  }
44→
45→  const historyEntries = entries.slice(0, currentIndex).map((e) => e.entry);
46→  if (historyEntries.length === 0) {
47→    return safeBody(currentEntry.body);
48→  }
49→
50→  const formatEntry = (entry: HistoryEntry) => `${entry.sender}: ${safeBody(entry.body)}`;
51→  return buildHistoryContextFromEntries({
52→    entries: [...historyEntries, currentEntry],
53→    currentMessage: formatEntry(currentEntry),
54→    formatEntry,
55→  });
56→}
