159→function resolveImageExtension(mimeType: string): string {
160→  const normalized = mimeType.toLowerCase();
161→  if (normalized.includes("png")) {
162→    return "png";
163→  }
164→  if (normalized.includes("jpeg") || normalized.includes("jpg")) {
165→    return "jpg";
166→  }
167→  if (normalized.includes("gif")) {
168→    return "gif";
169→  }
170→  if (normalized.includes("webp")) {
171→    return "webp";
172→  }
173→  return "bin";
