  7→function extractBetween(
  8→  input: string,
  9→  startMarker: string,
 10→  endMarker: string,
 11→): { text: string; found: boolean } {
 12→  const start = input.indexOf(startMarker);
 13→  if (start === -1) {
 14→    return { text: "", found: false };
 15→  }
 16→  const end = input.indexOf(endMarker, start + startMarker.length);
 17→  if (end === -1) {
 18→    return { text: input.slice(start), found: true };
 19→  }
 20→  return { text: input.slice(start, end), found: true };
 21→}
