 23→function parseSkillBlocks(skillsPrompt: string): Array<{ name: string; blockChars: number }> {
 24→  const prompt = skillsPrompt.trim();
 25→  if (!prompt) {
 26→    return [];
 27→  }
 28→  const blocks = Array.from(prompt.matchAll(/<skill>[\s\S]*?<\/skill>/gi)).map(
 29→    (match) => match[0] ?? "",
 30→  );
 31→  return blocks
 32→    .map((block) => {
 33→      const name = block.match(/<name>\s*([^<]+?)\s*<\/name>/i)?.[1]?.trim() || "(unknown)";
 34→      return { name, blockChars: block.length };
 35→    })
 36→    .filter((b) => b.blockChars > 0);
 37→}
