 69→function extractToolListText(systemPrompt: string): string {
 70→  const markerA = "Tool names are case-sensitive. Call tools exactly as listed.\n";
 71→  const markerB =
 72→    "\nTOOLS.md does not control tool availability; it is user guidance for how to use external tools.";
 73→  const extracted = extractBetween(systemPrompt, markerA, markerB);
 74→  if (!extracted.found) {
 75→    return "";
 76→  }
 77→  return extracted.text.replace(markerA, "").trim();
 78→}
