 80→export function buildSystemPromptReport(params: {
 81→  source: SessionSystemPromptReport["source"];
 82→  generatedAt: number;
 83→  sessionId?: string;
 84→  sessionKey?: string;
 85→  provider?: string;
 86→  model?: string;
 87→  workspaceDir?: string;
 88→  bootstrapMaxChars: number;
 89→  bootstrapTotalMaxChars?: number;
 90→  bootstrapTruncation?: SessionSystemPromptReport["bootstrapTruncation"];
 91→  sandbox?: SessionSystemPromptReport["sandbox"];
 92→  systemPrompt: string;
 93→  bootstrapFiles: WorkspaceBootstrapFile[];
 94→  injectedFiles: EmbeddedContextFile[];
 95→  skillsPrompt: string;
 96→  tools: AgentTool[];
 97→}): SessionSystemPromptReport {
 98→  const systemPrompt = params.systemPrompt.trim();
 99→  const projectContext = extractBetween(
100→    systemPrompt,
101→    "\n# Project Context\n",
102→    "\n## Silent Replies\n",
103→  );
104→  const projectContextChars = projectContext.text.length;
105→  const toolListText = extractToolListText(systemPrompt);
106→  const toolListChars = toolListText.length;
107→  const toolsEntries = buildToolsEntries(params.tools);
108→  const toolsSchemaChars = toolsEntries.reduce((sum, t) => sum + (t.schemaChars ?? 0), 0);
109→  const skillsEntries = parseSkillBlocks(params.skillsPrompt);
110→
111→  return {
112→    source: params.source,
113→    generatedAt: params.generatedAt,
114→    sessionId: params.sessionId,
115→    sessionKey: params.sessionKey,
116→    provider: params.provider,
117→    model: params.model,
118→    workspaceDir: params.workspaceDir,
119→    bootstrapMaxChars: params.bootstrapMaxChars,
120→    bootstrapTotalMaxChars: params.bootstrapTotalMaxChars,
121→    ...(params.bootstrapTruncation ? { bootstrapTruncation: params.bootstrapTruncation } : {}),
122→    sandbox: params.sandbox,
123→    systemPrompt: {
124→      chars: systemPrompt.length,
125→      projectContextChars,
126→      nonProjectContextChars: Math.max(0, systemPrompt.length - projectContextChars),
127→    },
128→    injectedWorkspaceFiles: buildBootstrapInjectionStats({
129→      bootstrapFiles: params.bootstrapFiles,
130→      injectedFiles: params.injectedFiles,
131→    }),
132→    skills: {
133→      promptChars: params.skillsPrompt.length,
134→      entries: skillsEntries,
135→    },
136→    tools: {
137→      listChars: toolListChars,
138→      schemaChars: toolsSchemaChars,
139→      entries: toolsEntries,
140→    },
141→  };
142→}
