 32→function extractErrorMessage(err: unknown): string | undefined {
 33→  if (!err) {
 34→    return undefined;
 35→  }
 36→  if (typeof err === "string") {
 37→    return err;
 38→  }
 39→  if (err instanceof Error) {
 40→    return err.message;
 41→  }
 42→  if (typeof err === "object" && "message" in err && typeof err.message === "string") {
 43→    return err.message;
 44→  }
 45→  if (typeof err === "number" || typeof err === "boolean" || typeof err === "bigint") {
 46→    return String(err);
 47→  }
 48→  if (typeof err === "symbol") {
 49→    return err.toString();
 50→  }
 51→  if (typeof err === "object") {
 52→    try {
 53→      return JSON.stringify(err);
 54→    } catch {
 55→      return undefined;
 56→    }
 57→  }
 58→  return undefined;
 59→}
