 61→function logRemoteBinProbeFailure(nodeId: string, err: unknown) {
 62→  const message = extractErrorMessage(err);
 63→  const label = describeNode(nodeId);
 64→  // Node unavailable errors (not connected or disconnected mid-operation) are expected
 65→  // when nodes have transient connections - log at info level instead of warn
 66→  if (message?.includes("node not connected") || message?.includes("node disconnected")) {
 67→    log.info(`remote bin probe skipped: node unavailable (${label})`);
 68→    return;
 69→  }
 70→  if (message?.includes("invoke timed out") || message?.includes("timeout")) {
 71→    log.warn(`remote bin probe timed out (${label}); check node connectivity for ${label}`);
 72→    return;
 73→  }
 74→  log.warn(`remote bin probe error (${label}): ${message ?? "unknown"}`);
 75→}
