 77→function isMacPlatform(platform?: string, deviceFamily?: string): boolean {
 78→  const platformNorm = String(platform ?? "")
 79→    .trim()
 80→    .toLowerCase();
 81→  const familyNorm = String(deviceFamily ?? "")
 82→    .trim()
 83→    .toLowerCase();
 84→  if (platformNorm.includes("mac")) {
 85→    return true;
 86→  }
 87→  if (platformNorm.includes("darwin")) {
 88→    return true;
 89→  }
 90→  if (familyNorm === "mac") {
 91→    return true;
 92→  }
 93→  return false;
 94→}
