187→    if (os.length > 0 && !os.includes(targetPlatform)) {
188→      continue;
189→    }
190→    const required = entry.metadata?.requires?.bins ?? [];
191→    const anyBins = entry.metadata?.requires?.anyBins ?? [];
192→    for (const bin of required) {
193→      if (bin.trim()) {
194→        bins.add(bin.trim());
195→      }
196→    }
197→    for (const bin of anyBins) {
198→      if (bin.trim()) {
199→        bins.add(bin.trim());
200→      }
201→    }
202→  }
203→  return [...bins];
204→}
