async fn skill_detail(&self, params: Value) -> ServiceResult {
    use moltis_skills::requirements::check_requirements;

    let source = params
        .get("source")
        .and_then(|v| v.as_str())
        .ok_or_else(|| "missing 'source' parameter".to_string())?;
