                 sidecar directory; omit file_path to read the body"
            ))
            .into());
        }
        return read_sidecar(name, &meta.path, rel).await;
    }

    let mut result = read_primary(name, meta).await?;
    inject_install_note(&mut result, &install_note);
    Ok(result)
}

