// ── Types ────────────────────────────────────────────────────

interface SkillSummary {
	name: string;
	description?: string;
	category?: string;
	source?: string;
	enabled?: boolean;
	protected?: boolean;
	display_name?: string;
	quarantined?: boolean;
	trusted?: boolean;
	drifted?: boolean;
	eligible?: boolean;
}
interface SkillDetail extends SkillSummary {
	body?: string;
	body_html?: string;
	author?: string;
	version?: string;
	homepage?: string;
	source_url?: string;
	commit_sha?: string;
	commit_url?: string;
	commit_age_days?: number;
	compatibility?: string;
	allowed_tools?: string[];
	license?: string;
	license_url?: string;
	missing_bins?: string[];
	install_options?: { label?: string; kind?: string }[];
	requires?: { bins?: string[]; any_bins?: string[] };
	provenance?: { original_source?: string; original_commit_sha?: string; imported_from?: string };
